# Bài giảng HSK 3 (HSK 3.0). Bài nào chưa có ở đây thì app chỉ dạy từ vựng + bài tập (4 bước).
# [từ] đánh dấu từ trọng tâm cho bài tập điền từ.
UNITS3 = [
# ---------------- 1
{"title":"Nhà mới","topic":"Nhà cửa, đồ dùng; câu 把 (1), 刚 / 刚才, bổ ngữ kết quả 到 / 住 / 走 / 上",
"goals":["Gọi tên phòng, đồ dùng trong nhà","Dùng câu 把 để nói đặt / chuyển đồ vật đi đâu","Phân biệt 刚 và 刚才","Dùng bổ ngữ kết quả 到, 住, 走, 上"],
"dialogue":[("小米","龙，听说你搬家了？新房子怎么样？","Long, nghe nói bạn chuyển nhà rồi à? Nhà mới thế nào?"),("龙","挺好的，在一个新小区，我住在十二层。","Khá tốt, ở một khu chung cư mới, mình ở tầng mười hai."),("小米","有电梯吗？","Có thang máy không?"),("龙","有。我刚搬进去，东西还没放好。","Có. Mình vừa dọn vào, đồ đạc còn chưa xếp xong."),("小米","我周末去帮你吧！你想把沙发放在哪儿？","Cuối tuần mình qua giúp nhé! Bạn muốn đặt sofa ở đâu?"),("龙","我想把沙发放在窗户旁边，把冰箱搬到厨房里。","Mình muốn đặt sofa cạnh cửa sổ, chuyển tủ lạnh vào bếp."),("小米","好。对了，你刚才说的邻居是谁？","Được. À, người hàng xóm bạn nói lúc nãy là ai?"),("龙","是一位老人，很热情。我已经记住他的名字了。","Là một cụ già, rất nhiệt tình. Mình đã nhớ được tên cụ rồi.")],
"grammar":[
{"title":"Câu 把 (1): đem cái gì đặt / chuyển tới đâu","formula":"Chủ ngữ + 把 + Vật + Động từ + 在 / 到 + Nơi chốn",
"explain":"Câu <b>把</b> nhấn mạnh việc <b>xử lý một vật cụ thể</b> và kết quả của việc đó. Mẫu hay gặp nhất là đặt / chuyển vật tới một chỗ:<br>我<b>把</b>沙发<b>放在</b>窗户旁边。 (Tôi đặt sofa cạnh cửa sổ.)<br>他<b>把</b>冰箱<b>搬到</b>厨房里。<br>Lưu ý: vật sau 把 phải <b>xác định</b> (người nghe biết là cái nào), và động từ <b>không đứng một mình</b> mà phải có phần sau (在…, 到…, 了, bổ ngữ…).",
"examples":[("我[把]沙发放在窗户旁边。","Tôi đặt sofa cạnh cửa sổ."),("请[把]书放在桌子上。","Hãy đặt sách lên bàn."),("他[把]冰箱搬到厨房里了。","Anh ấy chuyển tủ lạnh vào bếp rồi."),("你[把]手机放在哪儿了？","Bạn để điện thoại ở đâu rồi?")],
"note":"Sai: 我把沙发放。 (thiếu phần sau động từ). Phủ định đặt 没/不 trước 把: 我没把书放在桌子上。"},
{"title":"刚 và 刚才","formula":"刚 + Động từ (phó từ) · 刚才 (danh từ thời gian, đứng đầu câu hoặc trước động từ)",
"explain":"Cả hai đều nghĩa \"vừa mới\" nhưng khác loại từ:<br>• <b>刚 / 刚刚</b> là phó từ, đứng ngay trước động từ: 我<b>刚</b>到。 Có thể đi với thời lượng: 我刚来三天。<br>• <b>刚才</b> là danh từ chỉ thời điểm \"lúc nãy\", đứng được đầu câu, có thể đi với 不/没: <b>刚才</b>你去哪儿了？ 我刚才没听清楚。<br><b>刚才</b> chỉ vài phút trước; <b>刚</b> có thể là vài ngày trước (theo cảm nhận người nói).",
"examples":[("我[刚]搬进去。","Tôi vừa dọn vào."),("[刚才]你说什么？","Lúc nãy bạn nói gì?"),("他刚来中国三个月。","Anh ấy mới đến Trung Quốc ba tháng."),("[刚才]的电话是谁打的？","Cuộc gọi lúc nãy là ai gọi?")],
"note":"Sai: 刚你去哪儿了？ (刚 không đứng đầu câu). Sai: 我刚不在。 Đúng: 我刚才不在。"},
{"title":"Bổ ngữ kết quả: V + 到 / 住 / 走 / 上","formula":"Động từ + 到 (đạt được) / 住 (giữ chặt) / 走 (đi mất) / 上 (đóng, khép, đạt)",
"explain":"Thêm 4 bổ ngữ kết quả hay gặp:<br>• <b>到</b>: đạt được mục đích — 找<b>到</b> (tìm thấy), 买<b>到</b>, 收<b>到</b><br>• <b>住</b>: giữ lại, cố định — 记<b>住</b> (nhớ được), 站<b>住</b> (đứng lại)<br>• <b>走</b>: rời khỏi chỗ cũ — 拿<b>走</b> (cầm đi), 带<b>走</b><br>• <b>上</b>: khép lại / đạt tới — 关<b>上</b>门 (đóng cửa lại), 穿<b>上</b>, 考<b>上</b> (thi đỗ)<br>Phủ định dùng 没: 我没找到。",
"examples":[("我已经记[住]他的名字了。","Tôi đã nhớ được tên ông ấy rồi."),("你找[到]钥匙了吗？","Bạn tìm thấy chìa khóa chưa?"),("请关[上]门。","Làm ơn đóng cửa lại."),("谁把我的书拿[走]了？","Ai cầm mất sách của tôi rồi?")],
"note":"记得 (nhớ, còn nhớ) khác 记住 (ghi nhớ được, sau khi cố nhớ)."}],
"tip":"Ở Trung Quốc người ta hay mời hàng xóm, bạn bè tới \"温居\" (ăn mừng nhà mới). Khách thường mang quà nhỏ như trái cây."},
# ---------------- 2
{"title":"Đi khám bệnh","topic":"Cơ thể, ốm đau; câu bị động 被, …极了 / 得很 / 坏了, câu phản vấn 不是…吗",
"goals":["Mô tả triệu chứng: sốt, cảm, đau","Dùng câu bị động với 被","Nói mức độ cao: 好极了, 累坏了, 冷得很","Nhấn mạnh bằng câu phản vấn 不是…吗？"],
"dialogue":[("医生","你哪儿不舒服？","Bạn thấy khó chịu ở đâu?"),("龙","我头疼，还有点儿发烧。昨天晚上被雨淋了。","Tôi đau đầu, còn hơi sốt. Tối qua bị mưa ướt hết."),("医生","你没带伞吗？","Bạn không mang ô à?"),("龙","带了，可是我的伞被风刮坏了。","Có mang, nhưng ô của tôi bị gió thổi hỏng rồi."),("医生","是感冒。不是很严重，不用住院，多喝水，好好儿休息。","Là cảm. Không nghiêm trọng lắm, không cần nằm viện, uống nhiều nước, nghỉ ngơi cho tốt."),("龙","谢谢医生！我今天累坏了。","Cảm ơn bác sĩ! Hôm nay tôi mệt rã rời."),("小米","龙，你不是说今天去锻炼吗？","Long, chẳng phải bạn nói hôm nay đi tập à?"),("龙","不去了，先把身体养好。健康最重要！","Không đi nữa, phải dưỡng sức khỏe cho tốt trước. Sức khỏe quan trọng nhất!")],
"grammar":[
{"title":"Câu bị động với 被","formula":"Chủ ngữ (người/vật chịu tác động) + 被 + (Người làm) + Động từ + phần khác",
"explain":"Câu <b>被</b> dùng khi chủ ngữ <b>chịu</b> một tác động, thường là chuyện không mong muốn:<br>我的伞<b>被</b>风刮坏了。 (Ô của tôi bị gió thổi hỏng.)<br>Có thể bỏ người làm: 我的手机<b>被</b>拿走了。<br>Giống câu 把, động từ phải có phần sau (了, bổ ngữ…). Phủ định: <b>没被</b>: 我没被老师批评。",
"examples":[("我的伞[被]风刮坏了。","Ô của tôi bị gió thổi hỏng rồi."),("我的蛋糕[被]弟弟吃了。","Bánh của tôi bị em trai ăn mất."),("他[被]雨淋了。","Anh ấy bị mưa làm ướt."),("书[被]谁拿走了？","Sách bị ai cầm đi rồi?")],
"note":"So sánh: 风把伞刮坏了 (câu 把, nhấn người/vật gây ra) ↔ 伞被风刮坏了 (câu 被, nhấn vật bị ảnh hưởng). Hai câu cùng nghĩa."},
{"title":"Mức độ cao: Adj + 极了 / 得很 / 坏了","formula":"Tính từ + 极了 · Tính từ + 得很 · Tính từ/Động từ + 坏了",
"explain":"Ba cách nói \"cực kỳ\" đứng <b>sau</b> tính từ:<br>• <b>极了</b>: cực kỳ (khen hoặc chê đều được) — 好<b>极了</b>, 累<b>极了</b><br>• <b>得很</b>: rất (khẩu ngữ) — 冷<b>得很</b><br>• <b>坏了</b>: …muốn chết, …rã rời (thường với cảm giác khó chịu hoặc cảm xúc mạnh) — 累<b>坏了</b>, 饿<b>坏了</b>, 高兴<b>坏了</b>",
"examples":[("我今天累[坏了]。","Hôm nay tôi mệt rã rời."),("这个蛋糕好吃[极了]！","Cái bánh này ngon cực kỳ!"),("北方的冬天冷[得很]。","Mùa đông miền Bắc lạnh lắm."),("孩子们高兴坏了。","Bọn trẻ vui muốn xỉu.")],
"note":"Đã dùng 极了/得很/坏了 thì không thêm 很 phía trước: Sai: 很好极了。"},
{"title":"Câu phản vấn: 不是…吗？","formula":"不是 + … + 吗？ (= rõ ràng là…, sao lại…?)",
"explain":"Câu hỏi <b>không cần trả lời</b>, dùng để nhắc lại điều người nói cho là đúng, kèm chút ngạc nhiên hoặc trách nhẹ:<br>你<b>不是</b>说今天去锻炼<b>吗</b>？ (Chẳng phải bạn nói hôm nay đi tập sao?)",
"examples":[("你[不是]说今天去锻炼[吗]？","Chẳng phải bạn nói hôm nay đi tập sao?"),("你不是带伞了吗？","Chẳng phải bạn mang ô rồi sao?"),("他不是你的同学吗？","Cậu ấy chẳng phải bạn học của bạn sao?"),("今天不是星期六吗？","Hôm nay chẳng phải thứ bảy à?")],
"note":"Giọng điệu đi lên ở 吗, nhấn vào phần sau 不是."}],
"tip":"Đi khám ở Trung Quốc: đầu tiên 挂号 (lấy số), sau đó 看病 (khám), cuối cùng 拿药 (lấy thuốc)."},
# ---------------- 3
{"title":"Ăn gì cho ngon","topic":"Đồ ăn, đồ uống, dụng cụ ăn; 越来越, 越…越…, bổ ngữ khả năng 得 / 不",
"goals":["Gọi tên đồ ăn, đồ uống, bát đũa","Nói thay đổi theo thời gian với 越来越","Nói hai việc tăng cùng nhau với 越…越…","Nói có thể / không thể làm được bằng bổ ngữ khả năng"],
"dialogue":[("安娜","龙，你会用筷子吗？","Long, bạn biết dùng đũa không?"),("龙","会啊，我从小就用筷子。你呢？","Biết chứ, mình dùng đũa từ nhỏ. Còn bạn?"),("安娜","我来中国以后才开始学，现在用得越来越好了。","Mình sang Trung Quốc rồi mới bắt đầu học, giờ dùng càng ngày càng giỏi."),("龙","今天的菜太多了，我们吃得完吗？","Hôm nay đồ ăn nhiều quá, chúng ta ăn hết nổi không?"),("安娜","吃不完就带回家。这个蛋糕越吃越好吃！","Ăn không hết thì mang về nhà. Cái bánh này càng ăn càng ngon!"),("龙","你别吃太多甜的。要不要喝点儿饮料？","Bạn đừng ăn đồ ngọt nhiều quá. Có muốn uống chút gì không?"),("安娜","我要一瓶矿泉水，渴极了。","Mình lấy một chai nước khoáng, khát quá."),("龙","服务员，再给我们一个盘子和两个勺子，谢谢！","Phục vụ ơi, cho chúng tôi thêm một cái đĩa và hai cái thìa, cảm ơn!")],
"grammar":[
{"title":"越来越 + Tính từ: càng ngày càng…","formula":"Chủ ngữ + 越来越 + Tính từ / Động từ tâm lý",
"explain":"<b>越来越</b> diễn tả mức độ <b>tăng dần theo thời gian</b>: 天气<b>越来越</b>冷了。 Cuối câu thường có <b>了</b> (đã thay đổi).<br>Không dùng 很, 非常 sau 越来越: Sai: 越来越很好。",
"examples":[("我用筷子用得[越来越]好了。","Tôi dùng đũa càng ngày càng giỏi."),("天气[越来越]冷了。","Trời càng ngày càng lạnh."),("他[越来越]喜欢中国菜了。","Anh ấy càng ngày càng thích món Trung."),("城市越来越大了。","Thành phố càng ngày càng lớn.")],
"note":"越来越 + động từ tâm lý (喜欢, 想, 了解…) cũng được: 我越来越想家了。"},
{"title":"越 A 越 B: càng A càng B","formula":"Chủ ngữ + 越 + A + 越 + B",
"explain":"B thay đổi <b>theo</b> A: A càng nhiều/mạnh thì B càng…<br>这个蛋糕<b>越</b>吃<b>越</b>好吃。 (càng ăn càng ngon)<br>雨<b>越</b>下<b>越</b>大。 (mưa càng lúc càng to)<br>Hai vế có thể có chủ ngữ khác nhau: 你<b>越</b>说，他<b>越</b>生气。",
"examples":[("这个蛋糕[越]吃[越]好吃！","Cái bánh này càng ăn càng ngon!"),("雨[越]下[越]大。","Mưa càng lúc càng to."),("汉语越学越有意思。","Tiếng Trung càng học càng thú vị."),("你越说，他越生气。","Bạn càng nói, anh ấy càng giận.")],
"note":"越…越… không dùng với 很: Sai: 越吃越很好吃。"},
{"title":"Bổ ngữ khả năng: V + 得 / 不 + kết quả","formula":"Động từ + 得 + bổ ngữ (làm được) · Động từ + 不 + bổ ngữ (không làm được)",
"explain":"Chèn <b>得</b> (được) hoặc <b>不</b> (không) giữa động từ và bổ ngữ kết quả/xu hướng để nói <b>có khả năng đạt kết quả</b> hay không:<br>吃<b>得</b>完 (ăn hết được) / 吃<b>不</b>完 (ăn không hết)<br>看<b>得</b>懂 / 看<b>不</b>懂 · 听<b>得</b>清楚 / 听<b>不</b>清楚 · 回<b>得</b>来 / 回<b>不</b>来<br>Hỏi: 吃得完吃不完？ hoặc 吃得完吗？",
"examples":[("今天的菜太多了，我们吃[得]完吗？","Hôm nay đồ ăn nhiều quá, chúng ta ăn hết nổi không?"),("吃[不]完就带回家。","Ăn không hết thì mang về nhà."),("这本书你看得懂吗？","Quyển sách này bạn đọc hiểu được không?"),("太远了，我听不清楚。","Xa quá, tôi nghe không rõ.")],
"note":"不能吃完 (không được phép ăn hết) ≠ 吃不完 (không có khả năng ăn hết). Người Việt hay nhầm hai cái này."}],
"tip":"Trên bàn ăn Trung Quốc đừng cắm đũa thẳng đứng vào bát cơm, vì giống nén hương cúng người đã mất."},
# ---------------- 4
{"title":"Đi mua quần áo","topic":"Quần áo, thanh toán, tiền lẻ; so sánh 一样 / 更 / 不比, câu 把 (2)",
"goals":["Hỏi cỡ, đổi đồ, thanh toán bằng thẻ","So sánh bằng với 跟…一样","So sánh hơn với 更 / 还, và 不比","Dùng 把 + vật + 换成 / 给"],
"dialogue":[("龙","这件衬衫多少钱？","Cái áo sơ mi này bao nhiêu tiền?"),("服务员","一百八十九块五毛。您穿多大的？","Một trăm tám mươi chín tệ năm hào. Anh mặc cỡ bao nhiêu?"),("龙","这件有点儿小，能把它换成大一号的吗？","Cái này hơi nhỏ, đổi sang cỡ lớn hơn một số được không?"),("服务员","可以。这件大小跟那件一样，颜色不一样。","Được. Cái này cỡ giống cái kia, màu thì khác."),("龙","黄色的比蓝色的更好看。","Màu vàng đẹp hơn màu xanh."),("小米","我觉得蓝色的不比黄色的难看，还更便宜。","Mình thấy màu xanh không xấu hơn màu vàng, lại còn rẻ hơn."),("龙","好，就要蓝色的。可以用信用卡吗？","Được, lấy màu xanh. Dùng thẻ tín dụng được không?"),("服务员","可以，请把卡给我。一共一百五十块。","Được, xin đưa thẻ cho tôi. Tổng cộng một trăm năm mươi tệ.")],
"grammar":[
{"title":"So sánh bằng: A 跟 B 一样 (+ Tính từ)","formula":"A + 跟 + B + 一样 (+ Tính từ) · Phủ định: A + 跟 + B + 不一样",
"explain":"Nói A <b>giống</b> B: 这件<b>跟</b>那件<b>一样</b>。 Muốn nói giống ở điểm nào thì thêm tính từ: 我<b>跟</b>他<b>一样</b>高。 (Tôi cao bằng anh ấy.)<br>Phủ định đặt 不 trước 一样: 颜色<b>不一样</b>。",
"examples":[("这件大小[跟]那件[一样]。","Cái này cỡ giống cái kia."),("我跟他一样高。","Tôi cao bằng anh ấy."),("颜色不[一样]。","Màu không giống nhau."),("北京的冬天跟这儿不一样。","Mùa đông Bắc Kinh khác ở đây.")],
"note":"Sai: 我跟他一样很高。 Không thêm 很 sau 一样."},
{"title":"A 比 B 更 / 还 + Tính từ · A 不比 B + Tính từ","formula":"A + 比 + B + 更/还 + Tính từ · A + 不比 + B + Tính từ",
"explain":"<b>更 / 还</b> trước tính từ trong câu 比 nhấn mạnh \"hơn nữa\" (B vốn đã…, A còn…hơn): 黄色的比蓝色的<b>更</b>好看。<br><b>A 不比 B + Tính từ</b> nghĩa là \"A không hơn B\" (ngang ngang hoặc kém), thường để <b>phản bác</b> ý người khác: 蓝色的<b>不比</b>黄色的难看。 (Màu xanh đâu có xấu hơn màu vàng.)<br>Nhớ lại HSK 2: muốn nói \"kém\" thì dùng 没有.",
"examples":[("黄色的比蓝色的[更]好看。","Màu vàng đẹp hơn màu xanh."),("蓝色的[不比]黄色的难看。","Màu xanh không xấu hơn màu vàng."),("今天比昨天还冷。","Hôm nay còn lạnh hơn hôm qua."),("我不比你聪明。","Tôi đâu có thông minh hơn bạn.")],
"note":"更/还 dùng trong câu 比; 很/非常/太 thì KHÔNG dùng trong câu 比."},
{"title":"Câu 把 (2): 把 + vật + 换成 / 给 / 交给","formula":"Chủ ngữ + 把 + Vật + Động từ + 成 + Kết quả · 把 + Vật + 给 + Người",
"explain":"Hai mẫu câu 把 thường dùng khi mua bán:<br>• Đổi A thành B: 能<b>把</b>它<b>换成</b>大一号的吗？<br>• Đưa vật cho ai: 请<b>把</b>卡<b>给</b>我。 / <b>把</b>作业<b>交给</b>老师。",
"examples":[("能[把]它换成大一号的吗？","Đổi nó sang cỡ lớn hơn một số được không?"),("请[把]卡给我。","Xin đưa thẻ cho tôi."),("我想把美元换成人民币。","Tôi muốn đổi đô la sang nhân dân tệ."),("你把这本书给他吧。","Bạn đưa quyển sách này cho anh ấy đi.")],
"note":"Tiền Trung Quốc: 1 块 (元) = 10 毛 (角) = 100 分. Nói 189,5 tệ là 一百八十九块五(毛)."}],
"tip":"Ở Trung Quốc gần như ai cũng trả bằng điện thoại (微信支付, 支付宝). Người nước ngoài giờ cũng liên kết được thẻ Visa/Master vào hai app này."},
# ---------------- 5
{"title":"Bốn mùa và ngày lễ","topic":"Mùa, thời tiết, lễ tết, nghỉ lễ; 除了…以外, 该…了, 从…起",
"goals":["Nói về bốn mùa, gió, mặt trời, mặt trăng","Dùng 除了…以外 để nói \"ngoài… ra\"","Nhắc \"đến lúc làm gì rồi\" với 该…了","Nói mốc bắt đầu với 从…起"],
"dialogue":[("安娜","龙，越南有四季吗？","Long, Việt Nam có bốn mùa không?"),("龙","北方有四季，南方只有两个季节：雨季和旱季。","Miền Bắc có bốn mùa, miền Nam chỉ có hai mùa: mùa mưa và mùa khô."),("安娜","我最喜欢秋天，凉快极了。","Mình thích mùa thu nhất, mát cực kỳ."),("龙","中秋节的月亮特别大。除了吃月饼以外，我们还看月亮。","Trung thu trăng to đặc biệt. Ngoài ăn bánh trung thu ra, tụi mình còn ngắm trăng."),("安娜","我们国家除了新年以外，别的节日都不放假。","Nước mình ngoài năm mới ra, các ngày lễ khác đều không được nghỉ."),("龙","从下个星期起，我们放假，有七天假期。","Từ tuần sau trở đi tụi mình nghỉ, có bảy ngày nghỉ."),("安娜","太好了！我们该准备去旅游了。","Tuyệt quá! Đến lúc chuẩn bị đi du lịch rồi."),("龙","对，冬天快到了，该买大衣了。","Đúng, mùa đông sắp tới rồi, phải mua áo khoác thôi.")],
"grammar":[
{"title":"除了…以外，还 / 也 / 都…","formula":"除了 A (以外)，还/也 + B (thêm) · 除了 A (以外)，都 + … (loại trừ)",
"explain":"Hai nghĩa ngược nhau, phân biệt bằng phó từ ở vế sau:<br>• <b>还 / 也</b> = <b>bao gồm thêm</b>: <b>除了</b>吃月饼<b>以外</b>，我们<b>还</b>看月亮。 (ăn bánh, và còn ngắm trăng)<br>• <b>都</b> = <b>loại trừ</b>: <b>除了</b>新年<b>以外</b>，别的节日<b>都</b>不放假。 (trừ năm mới, các lễ khác đều không nghỉ)<br>以外 có thể bỏ.",
"examples":[("[除了]吃月饼[以外]，我们还看月亮。","Ngoài ăn bánh trung thu, chúng tôi còn ngắm trăng."),("[除了]新年以外，别的节日都不放假。","Trừ năm mới, các ngày lễ khác đều không nghỉ."),("除了汉语，他也会说英语。","Ngoài tiếng Trung, anh ấy cũng biết tiếng Anh."),("除了他，大家都来了。","Trừ anh ấy ra, mọi người đều đến rồi.")],
"note":"Nhìn phó từ vế sau: 还/也 → cộng thêm; 都 → trừ ra."},
{"title":"该…了: đến lúc… rồi","formula":"(Chủ ngữ) + 该 + Động từ + 了",
"explain":"<b>该…了</b> nhắc rằng <b>đã đến lúc phải làm gì</b> (theo lẽ thường hoặc theo thời gian):<br>十一点了，我<b>该</b>睡觉<b>了</b>。<br>冬天快到了，<b>该</b>买大衣<b>了</b>。",
"examples":[("我们[该]准备去旅游[了]。","Đến lúc chuẩn bị đi du lịch rồi."),("冬天快到了，[该]买大衣了。","Mùa đông sắp tới, phải mua áo khoác rồi."),("十一点了，你该睡觉了。","Mười một giờ rồi, em nên đi ngủ."),("该你了！","Đến lượt bạn rồi!")],
"note":"该 còn nghĩa là \"nên\" (= 应该): 你该多运动。"},
{"title":"从…起: từ… trở đi","formula":"从 + Thời điểm + 起 (+ Chủ ngữ + Động từ)",
"explain":"<b>从…起</b> chỉ mốc thời gian <b>bắt đầu</b> và kéo dài về sau:<br><b>从</b>下个星期<b>起</b>，我们放假。<br><b>从</b>今天<b>起</b>，我每天跑步。 Có thể nói 从…开始 với nghĩa giống.",
"examples":[("[从]下个星期[起]，我们放假。","Từ tuần sau trở đi, chúng tôi được nghỉ."),("[从]今天起，我每天学习汉语。","Từ hôm nay, ngày nào tôi cũng học tiếng Trung."),("从明年起，他在北京工作。","Từ năm sau, anh ấy làm việc ở Bắc Kinh."),("从那天起，我们成了朋友。","Từ hôm đó, chúng tôi thành bạn.")],
"note":"Chỉ dùng cho thời gian. Nơi chốn thì dùng 从…到… (đã học ở HSK 2)."}],
"tip":"Lễ lớn ở Trung Quốc: 春节 (Tết, nghỉ khoảng 8 ngày), 中秋节 (Trung thu), 国庆节 (Quốc khánh 1/10, nghỉ 7 ngày, đi đâu cũng đông)."},
# ---------------- 6
{"title":"Kể chuyện theo thứ tự","topic":"Mốc thời gian, trước sau; 才 và 就, 先…然后…最后, thời lượng sau sự việc",
"goals":["Dùng các từ chỉ thời gian: 以前, 以后, 后来, 最近, 前天…","Phân biệt 才 (muộn) và 就 (sớm)","Kể theo thứ tự với 先…然后…最后","Nói một việc đã xảy ra được bao lâu"],
"dialogue":[("王老师","龙，你来中国多长时间了？","Long, em đến Trung Quốc bao lâu rồi?"),("龙","我来中国半年了。以前我一直在越南学汉语。","Em đến Trung Quốc nửa năm rồi. Trước đây em vẫn học tiếng Trung ở Việt Nam."),("王老师","你今天怎么十点才来？","Hôm nay sao 10 giờ em mới đến?"),("龙","对不起，老师。地铁突然坏了，我等了半天。","Em xin lỗi thầy. Tàu điện ngầm đột nhiên hỏng, em đợi mãi."),("王老师","大卫八点就来了。你最近总是迟到。","David 8 giờ đã đến rồi. Gần đây em toàn đến muộn."),("龙","以后我先坐公交车，然后换地铁，最后走路过来。","Sau này em đi xe buýt trước, rồi đổi sang tàu điện ngầm, cuối cùng đi bộ tới."),("王老师","好。后天考试，你终于准备好了吗？","Được. Ngày kia thi, em chuẩn bị xong chưa?"),("龙","准备好了！我马上去复习。","Chuẩn bị xong rồi ạ! Em đi ôn bài ngay.")],
"grammar":[
{"title":"才 và 就: muộn và sớm","formula":"Thời gian + 才 + Động từ (muộn, khó) · Thời gian + 就 + Động từ + 了 (sớm, dễ)",
"explain":"Cùng đứng sau mốc thời gian nhưng thể hiện <b>cảm nhận của người nói</b>:<br>• <b>才</b>: muộn hơn mong đợi / khó khăn — 你怎么十点<b>才</b>来？ (10 giờ mới đến)<br>• <b>就</b>: sớm hơn mong đợi / dễ dàng — 大卫八点<b>就</b>来<b>了</b>。 (8 giờ đã đến rồi)<br>Câu 就 thường có 了 cuối, câu 才 thì <b>không</b> có 了.",
"examples":[("你怎么十点[才]来？","Sao 10 giờ bạn mới đến?"),("大卫八点[就]来了。","David 8 giờ đã đến rồi."),("他学了一年才会说。","Anh ấy học một năm mới biết nói."),("我看了一遍就懂了。","Tôi đọc một lần đã hiểu rồi.")],
"note":"Sai: 他十点才来了。 (才 không đi với 了 cuối câu)."},
{"title":"先…然后…最后…: trước tiên… sau đó… cuối cùng","formula":"先 + V1，然后 (再) + V2，最后 + V3",
"explain":"Kể các bước theo thứ tự. <b>先</b> và <b>再</b> là phó từ, đứng sau chủ ngữ; <b>然后</b>, <b>最后</b> đứng đầu vế câu:<br>我<b>先</b>坐公交车，<b>然后</b>换地铁，<b>最后</b>走路过来。",
"examples":[("我[先]坐公交车，[然后]换地铁。","Tôi đi xe buýt trước, rồi đổi sang tàu điện ngầm."),("我们先吃饭，然后去看电影。","Chúng ta ăn cơm trước, rồi đi xem phim."),("[最后]走路过来。","Cuối cùng đi bộ tới."),("你先洗手，再吃水果。","Con rửa tay trước rồi hãy ăn trái cây.")],
"note":"后来 (sau đó, chỉ chuyện đã qua) ≠ 然后 (rồi, dùng cả cho kế hoạch tương lai)."},
{"title":"Đã… được bao lâu: Động từ + (Tân ngữ) + Thời lượng + 了","formula":"Chủ ngữ + Động từ + Nơi/Tân ngữ + Thời lượng + 了",
"explain":"Với động từ xảy ra <b>một lần rồi duy trì trạng thái</b> (来, 到, 结婚, 毕业, 离开…), thời lượng đứng <b>sau</b> tân ngữ để nói từ lúc đó tới giờ đã bao lâu:<br>我来中国<b>半年了</b>。 (Tôi đến Trung Quốc được nửa năm rồi.)<br>他们结婚<b>三年了</b>。",
"examples":[("我来中国[半年]了。","Tôi đến Trung Quốc được nửa năm rồi."),("他们结婚三年了。","Họ cưới nhau được ba năm rồi."),("他离开北京很久了。","Anh ấy rời Bắc Kinh lâu rồi."),("你来中国多长时间了？","Bạn đến Trung Quốc bao lâu rồi?")],
"note":"Khác với HSK 2: 我学了三年汉语 (thời gian kéo dài của hành động học). Ở đây là khoảng thời gian <b>sau khi</b> việc xảy ra."}],
"tip":"Người Trung rất quý đúng giờ trong học tập, công việc. Đến muộn thì xin lỗi ngay: 对不起，我来晚了。"},
# ---------------- 7
{"title":"Đông Tây Nam Bắc","topic":"Phương hướng, đường phố; giới từ 向, 在…上/下/中, câu tồn hiện (xuất hiện)",
"goals":["Nói phương hướng Đông Tây Nam Bắc","Dùng 向 để chỉ hướng di chuyển hoặc đối tượng","Dùng 在…上 / 下 / 中 với nghĩa mở rộng","Mô tả có ai/cái gì xuất hiện ở đâu"],
"dialogue":[("游客","请问，火车站在哪个方向？","Xin hỏi, nhà ga ở hướng nào?"),("龙","在东边。您一直向东走，到了红绿灯向左拐。","Ở phía đông. Ông cứ đi thẳng về hướng đông, đến đèn giao thông thì rẽ trái."),("游客","附近有银行吗？","Gần đây có ngân hàng không?"),("龙","有，就在这条街中间，路边有很多人。","Có, ngay giữa con phố này, bên lề đường có nhiều người."),("游客","在北京，我常常找不到方向。","Ở Bắc Kinh tôi hay bị mất phương hướng."),("龙","北京的马路都是东西南北的，很容易记。","Đường ở Bắc Kinh đều theo Đông Tây Nam Bắc, rất dễ nhớ."),("游客","你看，前面走过来一个人，是不是警察？","Bạn nhìn kìa, phía trước có một người đi tới, có phải cảnh sát không?"),("龙","是的，您也可以向他问路。在生活中，大家都很热情。","Đúng vậy, ông cũng có thể hỏi đường anh ấy. Trong cuộc sống, mọi người đều rất nhiệt tình.")],
"grammar":[
{"title":"Giới từ 向: về phía, hướng tới (ai)","formula":"向 + Hướng/Nơi + Động từ · 向 + Người + Động từ (学习, 问, 介绍…)",
"explain":"<b>向</b> có hai cách dùng:<br>• Chỉ <b>hướng di chuyển</b> (gần nghĩa 往): <b>向</b>东走, <b>向</b>左拐<br>• Chỉ <b>đối tượng</b> của hành động: <b>向</b>他问路 (hỏi đường anh ấy), <b>向</b>老师学习 (học hỏi thầy)",
"examples":[("您一直[向]东走。","Ông cứ đi thẳng về hướng đông."),("到了红绿灯[向]左拐。","Đến đèn giao thông thì rẽ trái."),("您也可以[向]他问路。","Ông cũng có thể hỏi đường anh ấy."),("我们要向他学习。","Chúng ta phải học hỏi anh ấy.")],
"note":"往 chỉ dùng cho hướng di chuyển. Với người thì dùng 向: Sai: 往老师学习。"},
{"title":"在 + Danh từ + 上 / 下 / 中: nghĩa trừu tượng","formula":"在 + 生活/学习/工作/朋友的帮助 + 上 / 下 / 中",
"explain":"Ngoài nghĩa vị trí, 在…上/下/中 còn diễn tả <b>phương diện, điều kiện, quá trình</b>:<br>• 在…<b>上</b>: về mặt — 在学习<b>上</b> (về mặt học tập)<br>• 在…<b>下</b>: dưới điều kiện — 在老师的帮助<b>下</b> (nhờ sự giúp đỡ của thầy)<br>• 在…<b>中</b>: trong quá trình / phạm vi — 在生活<b>中</b> (trong cuộc sống)",
"examples":[("[在]生活[中]，大家都很热情。","Trong cuộc sống, mọi người đều rất nhiệt tình."),("在学习上，他很认真。","Về mặt học tập, anh ấy rất chăm chỉ."),("在老师的帮助下，我提高了很多。","Nhờ thầy giúp, tôi tiến bộ rất nhiều."),("这条街中间有一个银行。","Giữa con phố này có một ngân hàng.")],
"note":"中间 (ở giữa, vị trí cụ thể) khác 在…中 (trong, phạm vi trừu tượng)."},
{"title":"Câu tồn hiện: có ai/cái gì xuất hiện","formula":"Nơi chốn + Động từ + 过来/出来/进来… + (了) + Số lượng + Người/Vật",
"explain":"Mô tả <b>có người/vật xuất hiện</b> ở đâu đó, giống câu tồn tại ở HSK 2 nhưng dùng động từ chuyển động:<br>前面走<b>过来</b>一个人。 (Phía trước có một người đi tới.)<br>家里来<b>了</b>一位客人。 (Nhà có một vị khách đến.)<br>Người/vật mới xuất hiện đứng <b>sau</b> động từ và thường chưa xác định (一个人, 一位客人).",
"examples":[("前面走[过来]一个人。","Phía trước có một người đi tới."),("家里来了一位客人。","Nhà có một vị khách đến."),("教室里走出来两个学生。","Từ lớp học đi ra hai học sinh."),("路边停着很多汽车。","Bên lề đường đỗ nhiều ô tô.")],
"note":"Sai: 一个人前面走过来。 Nơi chốn đứng đầu, người xuất hiện đứng cuối."}],
"tip":"Bắc Kinh quy hoạch theo ô bàn cờ, nên người Bắc Kinh chỉ đường bằng 东西南北 chứ ít khi nói trái phải."},
# ---------------- 8
{"title":"Chuyến đi xa","topic":"Tàu cao tốc, hành lý, khách sạn; 只要…就, 如果…(的话)就, 一定 / 必须 / 不用",
"goals":["Nói chuyện đặt vé, lên tàu, khách sạn","Đặt điều kiện đủ với 只要…就","Giả định với 如果…(的话)，就","Nói mức bắt buộc: 必须, 一定, 不用"],
"dialogue":[("小米","龙，明天去上海，你准备好了吗？","Long, mai đi Thượng Hải, bạn chuẩn bị xong chưa?"),("龙","准备好了。我们坐高铁，八点出发。","Xong rồi. Tụi mình đi tàu cao tốc, 8 giờ xuất phát."),("小米","坐高铁必须带护照吗？","Đi tàu cao tốc bắt buộc mang hộ chiếu à?"),("龙","对，外国人一定要带护照。只要有护照，就可以检票上车。","Đúng, người nước ngoài nhất định phải mang hộ chiếu. Chỉ cần có hộ chiếu là soát vé lên tàu được."),("小米","如果高铁晚点的话，怎么办？","Nếu tàu cao tốc trễ giờ thì làm sao?"),("龙","不用担心，高铁很少晚点。","Không cần lo, tàu cao tốc rất ít khi trễ."),("小米","宾馆在哪儿？离车站远吗？","Khách sạn ở đâu? Cách ga có xa không?"),("龙","不远。我带了地图，只要跟着我走就行。","Không xa. Mình mang bản đồ rồi, chỉ cần đi theo mình là được.")],
"grammar":[
{"title":"只要…就…: chỉ cần… là…","formula":"只要 + Điều kiện，(Chủ ngữ) + 就 + Kết quả",
"explain":"<b>只要</b> nêu một <b>điều kiện đủ</b>: có điều kiện này là có kết quả, không cần gì thêm.<br><b>只要</b>有护照，<b>就</b>可以检票上车。<br>Sẽ học <b>只有…才…</b> (chỉ có… mới…) ở bài 10, nghĩa khác hẳn.",
"examples":[("[只要]有护照，[就]可以检票上车。","Chỉ cần có hộ chiếu là soát vé lên tàu được."),("只要跟着我走就行。","Chỉ cần đi theo tôi là được."),("只要你努力，就一定能学好。","Chỉ cần bạn cố gắng, nhất định học tốt."),("只要不下雨，我们就去爬山。","Chỉ cần không mưa, chúng ta sẽ đi leo núi.")],
"note":"就 đứng sau chủ ngữ của vế sau: 只要你来，我就高兴。 (Sai: 只要你来，就我高兴。)"},
{"title":"如果…(的话)，就…: nếu… thì…","formula":"如果 + Giả định (+ 的话)，(Chủ ngữ) + 就 + Kết quả",
"explain":"Câu giả định. <b>的话</b> đặt cuối vế giả định, có thể dùng cùng hoặc thay cho 如果:<br><b>如果</b>高铁晚点<b>的话</b>，怎么办？<br>明天下雨<b>的话</b>，我们<b>就</b>不去了。",
"examples":[("[如果]高铁晚点[的话]，怎么办？","Nếu tàu cao tốc trễ giờ thì làm sao?"),("如果你有时间，就来我家吧。","Nếu bạn có thời gian thì đến nhà tôi chơi nhé."),("明天下雨的话，我们就不去了。","Mai mưa thì chúng ta không đi nữa."),("如果我是你，我就去。","Nếu tôi là bạn, tôi sẽ đi.")],
"note":"Trong khẩu ngữ hay bỏ 如果, chỉ giữ 的话."},
{"title":"必须 · 一定 · 不用: mức độ bắt buộc","formula":"必须 + V (bắt buộc) · 一定 (要) + V (nhất định) · 不用 + V (không cần)",
"explain":"• <b>必须</b>: bắt buộc theo quy định: 坐高铁<b>必须</b>带证件。<br>• <b>一定 (要)</b>: nhấn mạnh quyết tâm hoặc lời dặn: 你<b>一定要</b>来！ <b>一定</b> còn nghĩa \"chắc chắn\": 他<b>一定</b>知道。<br>• <b>不用</b>: không cần (phủ định của 必须/要): <b>不用</b>担心。 Lưu ý phủ định của 必须 là <b>不用 / 不必</b>, không phải 不必须.",
"examples":[("坐高铁[必须]带护照吗？","Đi tàu cao tốc bắt buộc mang hộ chiếu à?"),("外国人[一定]要带护照。","Người nước ngoài nhất định phải mang hộ chiếu."),("[不用]担心。","Không cần lo."),("你一定要来！","Bạn nhất định phải đến nhé!")],
"note":"Sai: 你不必须来。 Đúng: 你不用来。"}],
"tip":"Mua vé tàu cao tốc Trung Quốc trên app 12306 (có tiếng Anh). Ga lớn kiểm tra an ninh như sân bay, nên đến sớm ít nhất 30 phút."},
# ---------------- 9
{"title":"Sở thích của em","topic":"Âm nhạc, phim, chụp ảnh; 不但…而且, 看起来 / 好像 / 看来, 一边…一边",
"goals":["Nói về sở thích giải trí, chụp ảnh, tin tức","Nối hai ý tăng tiến với 不但…而且","Đoán bằng 看起来, 好像, 看来","Nói làm hai việc cùng lúc với 一边…一边"],
"dialogue":[("安娜","龙，你平时喜欢做什么？","Long, ngày thường bạn thích làm gì?"),("龙","我喜欢拍照，也喜欢一边听音乐一边看书。","Mình thích chụp ảnh, cũng thích vừa nghe nhạc vừa đọc sách."),("安娜","你的相机看起来很新。","Máy ảnh của bạn trông mới quá."),("龙","是上个月买的。它不但很轻，而且照片特别好看。","Mua tháng trước. Nó không những nhẹ mà ảnh còn đẹp đặc biệt."),("安娜","你好像对画画儿也很感兴趣？","Hình như bạn cũng có hứng thú với vẽ tranh?"),("龙","对，我最喜爱的画家是徐悲鸿，他画的马很有名。","Đúng, họa sĩ mình thích nhất là Từ Bi Hồng, ngựa ông ấy vẽ rất nổi tiếng."),("安娜","看来你是个有文化的人！今天晚上有个音乐节目，一起去吗？","Xem ra bạn là người có văn hóa đấy! Tối nay có một chương trình ca nhạc, cùng đi không?"),("龙","好啊！我带上相机。","Được chứ! Mình mang theo máy ảnh.")],
"grammar":[
{"title":"不但…而且…: không những… mà còn…","formula":"(Chủ ngữ) + 不但 + A，而且 (还/也) + B",
"explain":"Nối hai ý theo hướng <b>tăng tiến</b> (B mạnh hơn hoặc thêm vào A):<br>它<b>不但</b>很轻，<b>而且</b>照片特别好看。<br>Nếu hai vế cùng chủ ngữ, chủ ngữ đứng <b>trước</b> 不但. Nếu khác chủ ngữ, mỗi chủ ngữ đứng sau liên từ: <b>不但</b>我去，<b>而且</b>他也去。",
"examples":[("它[不但]很轻，[而且]照片特别好看。","Nó không những nhẹ mà ảnh còn rất đẹp."),("他不但会说汉语，而且说得很好。","Anh ấy không những biết nói tiếng Trung mà còn nói rất giỏi."),("这儿的菜不但便宜，而且好吃。","Món ở đây không những rẻ mà còn ngon."),("不但我喜欢，而且我妈妈也喜欢。","Không chỉ tôi thích, mẹ tôi cũng thích.")],
"note":"Sai: 不但他会说汉语，而且说得很好。 (cùng chủ ngữ thì 他 phải đứng trước 不但)."},
{"title":"Đoán: 看起来 / 看上去 · 好像 · 看来","formula":"看起来/看上去 + Tính từ · 好像 + … · 看来，…",
"explain":"Ba cách đoán khác nhau:<br>• <b>看起来 / 看上去</b>: dựa vào <b>vẻ ngoài</b> — 你的相机<b>看起来</b>很新。<br>• <b>好像</b>: hình như, không chắc — 你<b>好像</b>对画画儿很感兴趣。<br>• <b>看来</b>: <b>rút ra kết luận</b> từ điều vừa thấy/nghe, đứng đầu câu — <b>看来</b>你是个有文化的人！",
"examples":[("你的相机[看起来]很新。","Máy ảnh của bạn trông mới quá."),("你[好像]对画画儿也很感兴趣？","Hình như bạn cũng thích vẽ tranh?"),("[看来]你是个有文化的人！","Xem ra bạn là người có văn hóa đấy!"),("他看上去很年轻。","Anh ấy trông rất trẻ.")],
"note":"好像 còn nghĩa \"giống như\": 她好像一个孩子。"},
{"title":"一边…一边…: vừa… vừa…","formula":"Chủ ngữ + 一边 + V1 + 一边 + V2",
"explain":"Làm <b>hai việc cùng lúc</b>, cùng một chủ ngữ:<br>我喜欢<b>一边</b>听音乐<b>一边</b>看书。<br>Khẩu ngữ có thể bỏ 一: 边吃边聊。",
"examples":[("我喜欢[一边]听音乐[一边]看书。","Tôi thích vừa nghe nhạc vừa đọc sách."),("我们一边吃饭一边聊天儿。","Chúng tôi vừa ăn cơm vừa nói chuyện."),("别一边走路一边玩手机。","Đừng vừa đi đường vừa chơi điện thoại."),("他一边唱一边跳。","Anh ấy vừa hát vừa nhảy.")],
"note":"Hai hành động phải làm được cùng lúc. Sai: 一边睡觉一边看书。"}],
"tip":"Từ Bi Hồng (徐悲鸿) là họa sĩ Trung Quốc nổi tiếng với tranh ngựa thủy mặc. Tranh ngựa thường được treo với ý \"马到成功\" (mã đáo thành công)."},
# ---------------- 10
{"title":"Kiên trì luyện tập","topic":"Thể thao, thi đấu; 只有…才, V + 起来 / 下去, câu lặp động từ",
"goals":["Nói về các môn thể thao, thi đấu, rèn luyện","Đặt điều kiện duy nhất với 只有…才","Nói bắt đầu (起来) và tiếp tục (下去)","Dùng câu lặp động từ để nói thời lượng / kết quả"],
"dialogue":[("大卫","龙，听说你参加了学校的运动会？","Long, nghe nói bạn tham gia hội thao của trường?"),("龙","对，我参加了羽毛球比赛，得了第二名。","Đúng, mình tham gia thi cầu lông, được giải nhì."),("大卫","真厉害！你练了多长时间？","Giỏi quá! Bạn luyện bao lâu?"),("龙","我打羽毛球打了三年了，每天都坚持锻炼。","Mình chơi cầu lông được ba năm rồi, ngày nào cũng kiên trì tập."),("大卫","我也想学，可是一打起来就累。","Mình cũng muốn học, nhưng hễ bắt đầu đánh là mệt."),("龙","刚开始都这样。只有坚持下去，水平才能提高。","Mới bắt đầu ai cũng vậy. Chỉ có kiên trì tiếp, trình độ mới nâng lên được."),("大卫","那你教我吧！这个周末去体育馆，怎么样？","Vậy bạn dạy mình đi! Cuối tuần này đi nhà thi đấu, thế nào?"),("龙","好啊，这是个好机会。我们一起努力！","Được, đây là cơ hội tốt. Chúng ta cùng cố gắng!")],
"grammar":[
{"title":"只有…才…: chỉ có… mới…","formula":"只有 + Điều kiện duy nhất，(Chủ ngữ) + 才 + Kết quả",
"explain":"<b>只有</b> nêu <b>điều kiện duy nhất / bắt buộc</b>: không có nó thì không có kết quả.<br><b>只有</b>坚持下去，水平<b>才</b>能提高。<br>So sánh: <b>只要…就</b> (bài 8) = điều kiện đủ, dễ; <b>只有…才</b> = điều kiện bắt buộc, khó.",
"examples":[("[只有]坚持下去，水平[才]能提高。","Chỉ có kiên trì tiếp, trình độ mới nâng lên."),("只有多练习，才能说得好。","Chỉ có luyện nhiều mới nói giỏi được."),("只有你去，他才会来。","Chỉ khi bạn đi, anh ấy mới đến."),("只有周末，我才有时间。","Chỉ cuối tuần tôi mới có thời gian.")],
"note":"Đi cặp cố định: 只要…就 · 只有…才. Không trộn 只有…就."},
{"title":"V + 起来 (bắt đầu) · V + 下去 (tiếp tục)","formula":"Động từ + 起来 (bắt đầu và tiếp diễn) · Động từ + 下去 (tiếp tục làm)",
"explain":"Nghĩa mở rộng của bổ ngữ xu hướng:<br>• <b>起来</b>: hành động <b>bắt đầu</b> rồi kéo dài — 一打<b>起来</b>就累, 他笑<b>起来</b>了, 下<b>起</b>雨<b>来</b>了 (tân ngữ chen giữa 起 và 来)<br>• <b>下去</b>: <b>tiếp tục</b> từ bây giờ về sau — 坚持<b>下去</b>, 说<b>下去</b>, 学<b>下去</b>",
"examples":[("我一打[起来]就累。","Hễ bắt đầu đánh là tôi mệt."),("只有坚持[下去]才能提高。","Chỉ có kiên trì tiếp mới tiến bộ."),("外面下起雨来了。","Bên ngoài bắt đầu mưa rồi."),("你说下去，我在听。","Bạn nói tiếp đi, tôi đang nghe.")],
"note":"Đã học 站起来 (đứng dậy) nghĩa hướng lên. 起来 ở đây là nghĩa \"bắt đầu\"."},
{"title":"Câu lặp động từ: V + O + V + 了 + thời lượng / 得 + …","formula":"Chủ ngữ + Động từ + Tân ngữ + Động từ (lặp) + 了 + Thời lượng · …+ 得 + Bổ ngữ",
"explain":"Khi động từ có tân ngữ mà muốn thêm <b>thời lượng</b> hoặc <b>bổ ngữ trạng thái</b>, phải <b>lặp động từ</b>:<br>我打羽毛球<b>打了</b>三年了。 (Tôi chơi cầu lông được ba năm rồi.)<br>他说汉语<b>说得</b>很好。 (đã gặp ở HSK 2)",
"examples":[("我打羽毛球[打]了三年了。","Tôi chơi cầu lông được ba năm rồi."),("他踢足球踢了两个小时。","Anh ấy đá bóng hai tiếng."),("她跳舞跳得很好。","Cô ấy nhảy rất đẹp."),("我等你等了半天。","Tôi đợi bạn mãi.")],
"note":"Sai: 我打羽毛球三年了 (thiếu động từ lặp, nghe như chưa xong câu). Cũng có thể nói: 我打了三年羽毛球。"}],
"tip":"Cầu lông (羽毛球) và bóng bàn (乒乓球) là hai môn rất phổ biến ở Trung Quốc. Sáng sớm ở công viên hay gặp các cụ tập thái cực quyền (太极拳)."},
# ---------------- 11
{"title":"Đi sở thú","topic":"Động vật, cây cỏ, môi trường; 为了 (mục đích), 关于 / 根据, 或者 khác 还是",
"goals":["Gọi tên động vật, cây cỏ, sông núi","Nói mục đích bằng 为了","Dùng 关于 (về) và 根据 (dựa vào)","Phân biệt 或者 (câu kể) và 还是 (câu hỏi)"],
"dialogue":[("小米","龙，周末我们去动物园吧！听说来了两只大熊猫。","Long, cuối tuần mình đi sở thú nhé! Nghe nói mới có hai con gấu trúc."),("龙","好啊！为了看大熊猫，我可以早点儿起床。","Được đó! Để xem gấu trúc, mình có thể dậy sớm một chút."),("小米","我们坐公交车去还是坐地铁去？","Mình đi xe buýt hay đi tàu điện ngầm?"),("龙","坐公交车或者地铁都可以，大概半个小时。","Xe buýt hoặc tàu điện ngầm đều được, khoảng nửa tiếng."),("小米","动物园里除了动物，还有一个很大的花园，花都开了。","Trong sở thú ngoài động vật còn có một vườn hoa rất lớn, hoa nở hết rồi."),("龙","我最近在看一本关于动物的书。","Dạo này mình đang đọc một quyển sách về động vật."),("小米","书里说什么？","Trong sách nói gì?"),("龙","根据书上说的，大熊猫一天要吃十几个小时。为了保护它们，环境很重要。","Theo sách nói, gấu trúc một ngày phải ăn hơn mười tiếng. Để bảo vệ chúng, môi trường rất quan trọng.")],
"grammar":[
{"title":"为了: để, vì (mục đích)","formula":"为了 + Mục đích，(Chủ ngữ) + Hành động",
"explain":"<b>为了</b> nêu <b>mục đích</b>, thường đứng ở vế đầu câu: <b>为了</b>看大熊猫，我早点儿起床。 (Để xem gấu trúc, tôi dậy sớm.)<br>Cũng dùng được trong 是为了 ở vế sau: 我学汉语<b>是为了</b>去中国工作。<br>Khác 因为 (vì, nguyên nhân): 因为下雨，我没去 (lý do) ↔ 为了身体，我每天跑步 (mục đích).",
"examples":[("[为了]看大熊猫，我可以早点儿起床。","Để xem gấu trúc, tôi có thể dậy sớm một chút."),("[为了]身体健康，他每天跑步。","Để có sức khỏe tốt, anh ấy chạy bộ mỗi ngày."),("我学汉语是[为了]去中国工作。","Tôi học tiếng Trung là để sang Trung Quốc làm việc."),("为了保护环境，我们少开车吧。","Để bảo vệ môi trường, chúng ta bớt lái xe đi.")],
"note":"Sai: 为了下雨，我没去。 (下雨 là nguyên nhân, phải dùng 因为)."},
{"title":"关于 (về) và 根据 (dựa vào, theo)","formula":"关于 + Chủ đề (+ 的 + Danh từ) · 根据 + Căn cứ，…",
"explain":"• <b>关于</b>: \"về\" một chủ đề. Hay đứng trước danh từ với 的: 一本<b>关于</b>动物<b>的</b>书 (một quyển sách về động vật), hoặc đầu câu: <b>关于</b>这个问题，我们明天再说。<br>• <b>根据</b>: \"dựa theo, căn cứ vào\" thông tin, quy định: <b>根据</b>天气预报，明天有雨。",
"examples":[("我在看一本[关于]动物的书。","Tôi đang đọc một quyển sách về động vật."),("[根据]书上说的，大熊猫很爱吃竹子。","Theo sách nói, gấu trúc rất thích ăn tre."),("关于这件事，你问老师吧。","Về việc này, bạn hỏi thầy giáo đi."),("根据天气预报，明天有雨。","Theo dự báo thời tiết, mai có mưa.")],
"note":"关于 chỉ \"nói về cái gì\"; 根据 chỉ \"căn cứ vào đâu mà nói\"."},
{"title":"或者 và 还是: hoặc","formula":"Câu kể: A 或者 B · Câu hỏi: A 还是 B？",
"explain":"Cả hai đều nghĩa \"hoặc\", nhưng:<br>• <b>或者</b> (hoặc 或) dùng trong <b>câu kể</b>: 坐公交车<b>或者</b>地铁都可以。<br>• <b>还是</b> dùng trong <b>câu hỏi lựa chọn</b>: 你坐公交车<b>还是</b>坐地铁？<br>Nhưng nếu câu hỏi nằm trong câu kể (\"tôi không biết A hay B\") thì vẫn dùng 还是: 我不知道他去<b>还是</b>不去。",
"examples":[("坐公交车[或者]地铁都可以。","Đi xe buýt hoặc tàu điện ngầm đều được."),("你喝茶[还是]喝咖啡？","Bạn uống trà hay cà phê?"),("周末我一般去公园或者在家看书。","Cuối tuần tôi thường đi công viên hoặc ở nhà đọc sách."),("我不知道他去还是不去。","Tôi không biết anh ấy đi hay không đi.")],
"note":"Sai: 你喝茶或者咖啡？ (câu hỏi phải dùng 还是)."}],
"tip":"Gấu trúc (大熊猫) là \"quốc bảo\" của Trung Quốc, quê ở Tứ Xuyên (四川). Thành Đô (成都) có trung tâm nuôi gấu trúc rất nổi tiếng."},
# ---------------- 12
{"title":"Ở trường","topic":"Trường lớp, sách vở; 其实, 又…又…, 一 + lượng từ + 也/都 + 不/没",
"goals":["Gọi tên đồ dùng học tập, lớp học, môn học","Dùng 其实 để nói \"thật ra\"","Miêu tả hai đặc điểm cùng lúc với 又…又…","Phủ định hoàn toàn: 一个也没有"],
"dialogue":[("妈妈","龙，放学了？今天作业多不多？","Long, tan học rồi à? Hôm nay bài tập có nhiều không?"),("龙","不多，就是数学作业又多又难。","Không nhiều, chỉ có bài tập toán vừa nhiều vừa khó."),("妈妈","你不是最喜欢数学吗？","Chẳng phải con thích toán nhất sao?"),("龙","其实我更喜欢语文。这个学期的数学课本太难了。","Thật ra con thích ngữ văn hơn. Sách toán học kỳ này khó quá."),("妈妈","那你先去图书馆复习一下吧。","Vậy con đến thư viện ôn một chút trước đi."),("龙","图书馆今天关门了。我的笔记本也忘在学校了。","Hôm nay thư viện đóng cửa rồi. Sổ ghi chép của con cũng để quên ở trường."),("妈妈","那问问你们班的同学吧。","Vậy hỏi bạn cùng lớp con đi."),("龙","我刚才问了，可是一个人也没回答我。当然，他们一般晚上才看手机。","Con vừa hỏi rồi, nhưng không ai trả lời con cả. Đương nhiên, họ thường tối mới xem điện thoại.")],
"grammar":[
{"title":"其实: thật ra","formula":"其实 + sự thật (khác với điều người ta nghĩ)",
"explain":"<b>其实</b> đưa ra <b>sự thật</b>, thường <b>trái</b> hoặc <b>bổ sung</b> cho điều vừa nói / điều người khác tưởng:<br>你以为我喜欢数学，<b>其实</b>我更喜欢语文。<br>Hay đứng đầu vế câu, hoặc sau chủ ngữ: 他<b>其实</b>不是老师。",
"examples":[("[其实]我更喜欢语文。","Thật ra tôi thích ngữ văn hơn."),("这个句子看起来很难，[其实]很简单。","Câu này trông khó, thật ra rất đơn giản."),("他其实不是我们学校的学生。","Cậu ấy thật ra không phải học sinh trường mình."),("其实我也不知道。","Thật ra tôi cũng không biết.")],
"note":"其实 khác 当然 (đương nhiên): 当然 xác nhận điều ai cũng nghĩ; 其实 nói điều người ta không nghĩ tới."},
{"title":"又 A 又 B: vừa A vừa B","formula":"又 + Tính từ/Động từ + 又 + Tính từ/Động từ",
"explain":"Nói <b>hai đặc điểm cùng lúc</b>, hai cái phải <b>cùng chiều</b> (cùng tốt hoặc cùng xấu):<br>数学作业<b>又</b>多<b>又</b>难。 (vừa nhiều vừa khó)<br>这个苹果<b>又</b>大<b>又</b>甜。 (vừa to vừa ngọt)<br>Không thêm 很 sau 又.",
"examples":[("数学作业[又]多[又]难。","Bài tập toán vừa nhiều vừa khó."),("这个苹果[又]大[又]甜。","Quả táo này vừa to vừa ngọt."),("我们的校长又年轻又热情。","Hiệu trưởng chúng tôi vừa trẻ vừa nhiệt tình."),("他又会唱歌又会跳舞。","Cậu ấy vừa biết hát vừa biết nhảy.")],
"note":"Sai: 又很多又很难。 Sai: 又便宜又不好 (hai ý ngược chiều thì nên dùng 虽然…但是…)."},
{"title":"一 + Lượng từ + (Danh từ) + 也 / 都 + 不 / 没: không… nào cả","formula":"一 + Lượng từ (+ Danh từ) + 也/都 + 不/没 + Động từ",
"explain":"Phủ định <b>hoàn toàn</b>, nhấn mạnh \"một cái cũng không\":<br><b>一</b>个人<b>也没</b>回答我。 (Không một ai trả lời tôi.)<br>我<b>一</b>本书<b>都没</b>带。 (Tôi chẳng mang quyển sách nào.)<br>Tân ngữ được đưa lên trước động từ.",
"examples":[("[一]个人[也]没回答我。","Không một ai trả lời tôi cả."),("我[一]本书[都]没带。","Tôi chẳng mang quyển sách nào."),("今天我一点儿也不累。","Hôm nay tôi chẳng mệt chút nào."),("这个字我一次也没写对。","Chữ này tôi chưa viết đúng lần nào.")],
"note":"一点儿也不 + Tính từ là cách nói rất hay dùng: 一点儿也不难 (chẳng khó chút nào)."}],
"tip":"Học sinh Trung Quốc học 6 năm tiểu học (小学), 3 năm trung học cơ sở (初中), 3 năm trung học phổ thông (高中), rồi thi đại học 高考."},
# ---------------- 13
{"title":"Học ngoại ngữ","topic":"Trình độ, điểm số, học ngôn ngữ; 遍 khác 次, 好/难/容易 + Động từ, bổ ngữ kết quả 清楚 / 明白 / 懂",
"goals":["Nói về trình độ, điểm số, cách học ngoại ngữ","Phân biệt 遍 (trọn một lượt) và 次 (lần)","Nói \"dễ làm / khó làm\": 好学, 难懂, 容易记","Dùng 听清楚, 看明白, 听懂"],
"dialogue":[("老师","龙，这次考试你的成绩提高了不少！","Long, lần thi này điểm của em tăng không ít!"),("龙","谢谢老师！我每天都很认真地复习。","Em cảm ơn cô! Ngày nào em cũng ôn rất chăm chỉ."),("老师","你是怎么学的？","Em học thế nào?"),("龙","我先把课文听三遍，再试着自己读，不认得的字就查词典。","Em nghe bài khóa ba lượt trước, rồi thử tự đọc, chữ nào không biết thì tra từ điển."),("老师","很好。你觉得汉语难学吗？","Rất tốt. Em thấy tiếng Trung có khó học không?"),("龙","汉字很难记，可是语法比较容易。有时候老师说得太快，我听不清楚。","Chữ Hán rất khó nhớ, nhưng ngữ pháp khá dễ. Có lúc cô nói nhanh quá, em nghe không rõ."),("老师","听不明白就问我，可以再说一遍。","Nghe không hiểu thì hỏi cô, cô có thể nói lại một lượt."),("龙","好的！我打算明年去中国留学，提高我的汉语水平。","Dạ! Em định năm sau sang Trung Quốc du học, nâng cao trình độ tiếng Trung.")],
"grammar":[
{"title":"遍 và 次: lần, lượt","formula":"Động từ + Số + 遍 / 次 (+ Tân ngữ)",
"explain":"Cả hai là lượng từ cho hành động (bổ ngữ động lượng):<br>• <b>次</b>: đếm <b>số lần</b> xảy ra: 我去过北京两<b>次</b>。<br>• <b>遍</b>: nhấn mạnh làm <b>trọn vẹn từ đầu đến cuối</b> một lượt: 我把课文听了三<b>遍</b>。 请再说一<b>遍</b>。<br>Đọc / nghe / viết / nói lại cả bài → dùng 遍.",
"examples":[("我把课文听了三[遍]。","Tôi nghe bài khóa ba lượt."),("请再说一[遍]。","Làm ơn nói lại một lượt."),("我去过中国两[次]。","Tôi đã đến Trung Quốc hai lần."),("这本书我看了两遍。","Quyển sách này tôi đọc hai lượt rồi.")],
"note":"再说一遍 (nói lại lần nữa từ đầu) là câu cực kỳ hay dùng trong lớp."},
{"title":"好 / 难 / 容易 + Động từ: dễ làm, khó làm","formula":"好 / 难 / 容易 + Động từ (thành một tính từ)",
"explain":"Ghép trước động từ để nói việc đó dễ hay khó:<br>• <b>好</b> + V: dễ (và dễ chịu): 好学, 好吃, 好看, 好找<br>• <b>难</b> + V: khó: 难学, 难懂, 难记, 难看 (xấu), 难听 (khó nghe)<br>• <b>容易</b> + V: dễ: 容易记, 容易懂<br>Dùng như tính từ: 汉字很<b>难记</b>。",
"examples":[("汉字很[难]记。","Chữ Hán rất khó nhớ."),("你觉得汉语[难]学吗？","Bạn thấy tiếng Trung khó học không?"),("这个句子很[容易]懂。","Câu này rất dễ hiểu."),("他家很好找。","Nhà anh ấy rất dễ tìm.")],
"note":"容易 còn nghĩa \"dễ bị\": 冬天容易感冒 (mùa đông dễ bị cảm)."},
{"title":"Bổ ngữ kết quả: 清楚 / 明白 / 懂","formula":"听 / 看 / 说 / 写 + 清楚 / 明白 / 懂",
"explain":"Ba bổ ngữ nói về <b>hiểu và rõ</b>:<br>• <b>清楚</b>: rõ ràng (nghe rõ, nhìn rõ, nói rõ): 听<b>清楚</b>, 说<b>清楚</b><br>• <b>明白</b>: hiểu ra ý: 听<b>明白</b>, 看<b>明白</b><br>• <b>懂</b>: hiểu nội dung (ngôn ngữ): 听<b>懂</b>, 看<b>懂</b><br>Kết hợp bổ ngữ khả năng: 听<b>得</b>清楚 / 听<b>不</b>清楚.",
"examples":[("老师说得太快，我听不[清楚]。","Cô nói nhanh quá, tôi nghe không rõ."),("听不[明白]就问我。","Nghe không hiểu thì hỏi tôi."),("这本书你看得[懂]吗？","Quyển sách này bạn đọc hiểu được không?"),("请你说清楚一点儿。","Bạn nói rõ hơn một chút đi.")],
"note":"听清楚 = nghe rõ tiếng; 听懂 = hiểu nghĩa. Nghe rõ chưa chắc đã hiểu!"}],
"tip":"Muốn nghe tốt hãy luyện \"nghe lặp\" (精听): một đoạn ngắn nghe nhiều lượt (遍) tới khi chép lại được từng chữ."},
# ---------------- 14
{"title":"Ở công ty","topic":"Văn phòng, họp, email; 怎么办 / 有什么办法, 决定 / 要求 / 打算 + việc, câu hỏi 是不是",
"goals":["Nói chuyện ở văn phòng: họp, xin nghỉ, gửi email","Hỏi cách giải quyết: 怎么办？ 有什么办法？","Dùng 决定 / 要求 / 打算 + một việc","Hỏi xác nhận bằng 是不是"],
"dialogue":[("同事","龙，你今天是不是迟到了？经理刚才找你。","Long, hôm nay bạn đến muộn phải không? Giám đốc vừa tìm bạn."),("龙","是啊，路上车太多了。经理找我有什么事？","Ừ, trên đường xe đông quá. Giám đốc tìm mình có việc gì?"),("同事","下午三点开会，经理要求每个人都把工作完成。","Ba giờ chiều họp, giám đốc yêu cầu mọi người đều phải làm xong việc."),("龙","不好了，我的报告还没写完。怎么办？","Chết rồi, báo cáo của mình chưa viết xong. Làm sao bây giờ?"),("同事","别着急，我们一起想想办法。你先写最重要的。","Đừng vội, chúng ta cùng nghĩ cách. Bạn viết phần quan trọng nhất trước."),("龙","好。对了，你收到我的邮件了吗？里面有会议的名单。","Được. À, bạn nhận được email của mình chưa? Trong đó có danh sách cuộc họp."),("同事","收到了。我明天要请假，已经决定去看医生。","Nhận rồi. Mai mình xin nghỉ, đã quyết định đi khám bác sĩ."),("龙","没问题，你的工作我来办。","Không sao, việc của bạn để mình lo.")],
"grammar":[
{"title":"怎么办？ / 有什么办法？: làm sao bây giờ?","formula":"(Tình huống)，怎么办？ · 有什么办法 + (V)？ · 想办法 + V",
"explain":"• <b>怎么办</b>: \"làm thế nào bây giờ?\", đứng cuối câu sau khi nêu vấn đề: 报告还没写完，<b>怎么办</b>？<br>• <b>有什么办法</b>: \"có cách gì không?\": 你<b>有什么办法</b>吗？<br>• <b>想办法</b> (+ V): nghĩ cách (làm gì): 我们一起<b>想</b>想<b>办法</b>。<br><b>办法</b> là cách giải quyết một vấn đề cụ thể; <b>方法</b> là phương pháp chung (学习方法).",
"examples":[("我的报告还没写完，[怎么办]？","Báo cáo của tôi chưa viết xong, làm sao bây giờ?"),("我们一起想想[办法]。","Chúng ta cùng nghĩ cách đi."),("你有什么好方法学汉字吗？","Bạn có phương pháp hay để học chữ Hán không?"),("手机丢了，怎么办？","Mất điện thoại rồi, làm sao đây?")],
"note":"没办法 = hết cách, đành chịu: 下雨了，没办法，只能在家。"},
{"title":"决定 / 要求 / 打算 + một việc","formula":"决定 / 打算 + Động từ… · 要求 + Người + Động từ…",
"explain":"Ba động từ này mang tân ngữ là <b>cả một việc</b> (cụm động từ):<br>• 我<b>决定</b>去看医生。 (quyết định làm gì)<br>• 我<b>打算</b>明年去中国。 (dự định)<br>• 经理<b>要求</b>我们把工作完成。 (yêu cầu ai làm gì, giống câu kiêm ngữ với 让)<br>决定 / 要求 cũng là danh từ: 这是经理的<b>决定</b>。",
"examples":[("我已经[决定]去看医生。","Tôi đã quyết định đi khám bác sĩ."),("经理[要求]每个人都把工作完成。","Giám đốc yêu cầu mọi người đều làm xong việc."),("你周末[打算]做什么？","Cuối tuần bạn định làm gì?"),("老师要求我们每天复习。","Thầy yêu cầu chúng tôi ôn bài mỗi ngày.")],
"note":"打算 nhẹ hơn 决定: 打算 còn có thể đổi ý, 决定 là đã chốt."},
{"title":"Câu hỏi 是不是: phải không?","formula":"Chủ ngữ + 是不是 + Vị ngữ？ · Câu kể，是不是？",
"explain":"Dùng khi người hỏi <b>đã đoán</b> và muốn xác nhận:<br>你今天<b>是不是</b>迟到了？ (Hôm nay bạn đến muộn phải không?)<br>Có thể đặt cuối câu: 你迟到了，<b>是不是</b>？<br>So với 吗: 你迟到了吗？ chỉ hỏi bình thường; 是不是 cho thấy người hỏi gần như chắc chắn.",
"examples":[("你今天[是不是]迟到了？","Hôm nay bạn đến muộn phải không?"),("他[是不是]生病了？","Anh ấy bị ốm phải không?"),("明天开会，是不是？","Mai họp, phải không?"),("你是不是不喜欢这个工作？","Có phải bạn không thích công việc này không?")],
"note":"Trả lời: 是 / 是啊 (đúng vậy) hoặc 不是 (không phải)."}],
"tip":"Ở công ty Trung Quốc người ta hay gọi nhau bằng 姓 + chức vụ: 王经理, 李老师, hoặc 小 + họ cho người trẻ (小李), 老 + họ cho người lớn tuổi (老张)."},
# ---------------- 15
{"title":"Điện thoại và đồ điện","topic":"Đồ điện tử, giấy tờ, an toàn; 用 + vật + làm gì, 借给 / 跟…借, 小心 / 注意 + việc",
"goals":["Gọi tên đồ điện, nói bật / tắt, sạc, mất đồ","Nói dùng cái gì để làm gì với 用","Phân biệt 借给 (cho mượn) và 跟…借 (mượn của ai)","Nhắc nhở với 小心 / 注意"],
"dialogue":[("安娜","龙，我的手机没电了，关机了。","Long, điện thoại mình hết pin, tắt nguồn rồi."),("龙","用我的吧。你要做什么？","Dùng của mình đi. Bạn cần làm gì?"),("安娜","我要用手机给妈妈发一个邮件。对了，你能把耳机借给我吗？","Mình cần dùng điện thoại gửi email cho mẹ. À, bạn cho mình mượn tai nghe được không?"),("龙","可以，不过我昨天跟小米借了一个，我的丢了。","Được, nhưng hôm qua mình mượn của Tiểu Mễ một cái, cái của mình mất rồi."),("安娜","你又丢东西了！你应该注意一点儿。","Bạn lại làm mất đồ rồi! Bạn nên chú ý một chút."),("龙","哈哈，你说得对。这个房间的灯怎么开？","Haha, bạn nói đúng. Đèn phòng này bật thế nào?"),("安娜","在门旁边。小心，那里的电不太安全，我已经请人来检查了。","Ở cạnh cửa. Cẩn thận, điện ở đó không an toàn lắm, mình đã gọi người tới kiểm tra rồi."),("龙","好，我会小心的。用手机打电话真方便！","Được, mình sẽ cẩn thận. Dùng điện thoại gọi điện thật tiện!")],
"grammar":[
{"title":"用 + Vật + Động từ: dùng cái gì để làm gì","formula":"Chủ ngữ + 用 + Công cụ + Động từ (+ Tân ngữ)",
"explain":"<b>用</b> giới thiệu <b>công cụ / cách thức</b>, đứng trước động từ chính:<br>我<b>用</b>手机给妈妈发信息。 (Tôi dùng điện thoại gửi tin cho mẹ.)<br>他<b>用</b>汉语回答问题。 (Anh ấy trả lời bằng tiếng Trung.)<br>Người Việt hay nói \"gửi tin bằng điện thoại\" (đặt sau), tiếng Trung phải đặt <b>用…</b> lên trước động từ.",
"examples":[("我要[用]手机给妈妈发一个邮件。","Tôi cần dùng điện thoại gửi một email cho mẹ."),("[用]手机打电话真方便！","Dùng điện thoại gọi điện thật tiện!"),("请用铅笔写。","Hãy viết bằng bút chì."),("他用汉语回答了问题。","Anh ấy trả lời câu hỏi bằng tiếng Trung.")],
"note":"Sai: 我发信息用手机。 Đúng: 我用手机发信息。"},
{"title":"借给 và 跟 / 向…借: cho mượn, mượn","formula":"A + 把 + Vật + 借给 + B (A cho B mượn) · B + 跟 / 向 + A + 借 + Vật (B mượn của A)",
"explain":"<b>借</b> có hai chiều, phải nhìn giới từ:<br>• <b>借给</b> + người: <b>cho</b> ai mượn: 你能把耳机<b>借给</b>我吗？<br>• <b>跟 / 向</b> + người + <b>借</b>: mượn <b>của</b> ai: 我<b>跟</b>小米<b>借</b>了一个耳机。<br>Trả lại: 还 (huán) + 给: 明天还给你。",
"examples":[("你能把耳机[借给]我吗？","Bạn cho tôi mượn tai nghe được không?"),("我[跟]小米借了一个耳机。","Tôi mượn của Tiểu Mễ một cái tai nghe."),("这本书是我向图书馆借的。","Quyển sách này tôi mượn ở thư viện."),("我明天还给你。","Mai tôi trả lại bạn.")],
"note":"Sai: 我借小米耳机 (không rõ ai cho ai mượn). Nhớ: 借给 = cho mượn, 跟…借 = mượn."},
{"title":"小心 / 注意 + việc: cẩn thận, chú ý","formula":"小心 (+ Động từ / Danh từ)！ · 注意 + Danh từ / Động từ",
"explain":"• <b>小心</b>: cẩn thận, có thể đứng một mình như lời cảnh báo: <b>小心</b>！ <b>小心</b>车！ 我会<b>小心</b>的。<br>• <b>注意</b>: chú ý, để tâm tới: <b>注意</b>安全, <b>注意</b>身体, 你应该<b>注意</b>一点儿。<br>会…的: khẳng định chắc chắn sẽ làm: 我<b>会</b>小心<b>的</b>。",
"examples":[("[小心]，那里的电不太安全。","Cẩn thận, điện ở đó không an toàn lắm."),("你应该[注意]一点儿。","Bạn nên chú ý một chút."),("我会[小心]的。","Tôi sẽ cẩn thận."),("天冷了，注意身体。","Trời lạnh rồi, giữ gìn sức khỏe nhé.")],
"note":"注意安全 (chú ý an toàn) và 小心地滑 (cẩn thận sàn trơn) là hai biển báo rất hay gặp."}],
"tip":"Người Trung Quốc gần như trả mọi thứ bằng điện thoại: 微信支付 (WeChat Pay) và 支付宝 (Alipay). Đi đâu cũng thấy mã QR."},
# ---------------- 16
{"title":"Người thân và bạn bè","topic":"Các mối quan hệ, làm khách, tặng quà; 咱们 và 我们, 跟 + người + 见面 / 结婚, 对 + người + 好 / 热情",
"goals":["Nói về các mối quan hệ, làm khách, tặng quà","Phân biệt 咱们 và 我们","Dùng 跟 + người + 见面 / 结婚 / 聊天","Nói thái độ với ai: 对他很好, 对客人很热情"],
"dialogue":[("龙","安娜，周六咱们一起去叔叔家做客吧。","Anna, thứ bảy chúng ta cùng đến nhà chú làm khách nhé."),("安娜","好啊！我应该带什么礼物？","Được đó! Mình nên mang quà gì?"),("龙","带点儿水果就行。我叔叔和阿姨对客人特别热情。","Mang ít trái cây là được. Chú và cô mình rất nhiệt tình với khách."),("安娜","他们结婚多少年了？","Họ kết hôn bao nhiêu năm rồi?"),("龙","二十多年了。他们是在大学认识的，第一次见面就成了好朋友。","Hơn hai mươi năm rồi. Họ quen nhau ở đại học, lần đầu gặp đã thành bạn tốt."),("安娜","真好！我也想早点儿跟你的家人见面。","Hay quá! Mình cũng muốn sớm gặp gia đình bạn."),("龙","我叔叔对我很好，我来这儿上大学以后，一直是他们照顾我。","Chú mình đối với mình rất tốt, từ khi mình đến đây học đại học, luôn là cô chú chăm sóc mình."),("安娜","那这次我们请他们吃饭吧，谢谢他们。","Vậy lần này chúng ta mời cô chú ăn cơm đi, để cảm ơn họ.")],
"grammar":[
{"title":"咱们 và 我们: chúng ta, chúng tôi","formula":"咱们 = người nói + người nghe · 我们 = người nói (+ có thể có người nghe)",
"explain":"• <b>咱们</b> luôn <b>bao gồm người nghe</b>, giống \"chúng ta / mình\": <b>咱们</b>一起去吧！ (khẩu ngữ, phía Bắc hay dùng)<br>• <b>我们</b> có thể có hoặc không có người nghe, giống \"chúng tôi\" hoặc \"chúng ta\": <b>我们</b>是越南人，你们呢？<br>Khi nói với người ngoài nhóm, chỉ dùng 我们.",
"examples":[("周六[咱们]一起去叔叔家做客吧。","Thứ bảy chúng ta cùng đến nhà chú làm khách nhé."),("[我们]是越南人，你们呢？","Chúng tôi là người Việt Nam, còn các bạn?"),("咱们走吧！","Mình đi thôi!"),("老师，我们明天考试吗？","Thầy ơi, mai chúng em thi ạ?")],
"note":"Sai: 咱们是学生，你们是老师。 (咱们 đã gồm người nghe, không thể đối lập với 你们)."},
{"title":"跟 + Người + 见面 / 结婚 / 聊天","formula":"A + 跟 + B + 见面 / 结婚 / 聊天 / 一起…",
"explain":"Một số động từ \"hai người cùng làm\" là <b>động từ ly hợp</b>, <b>không</b> mang tân ngữ chỉ người phía sau, mà phải đưa người lên trước bằng <b>跟</b>:<br>我想<b>跟</b>你的家人<b>见面</b>。 (Sai: 我想见面你的家人。)<br>他<b>跟</b>她<b>结婚</b>了。 (Sai: 他结婚她。)",
"examples":[("我想早点儿[跟]你的家人见面。","Tôi muốn sớm gặp gia đình bạn."),("他[跟]大学同学结婚了。","Anh ấy cưới bạn học đại học."),("我常常跟奶奶聊天儿。","Tôi hay trò chuyện với bà."),("明天我跟朋友见面。","Mai tôi gặp bạn bè.")],
"note":"见 thì có thể mang tân ngữ: 我想见你的家人。 Nhưng 见面 thì không."},
{"title":"对 + Người + 好 / 热情: đối với ai thế nào","formula":"A + 对 + B + (很) + Tính từ (好 / 热情 / 关心…)",
"explain":"<b>对</b> giới thiệu <b>đối tượng</b> mà thái độ hướng tới:<br>我叔叔<b>对</b>我很好。 (Chú đối với tôi rất tốt.)<br>他们<b>对</b>客人特别热情。<br>Cũng dùng với động từ tâm lý: <b>对</b>这个问题很关心.",
"examples":[("我叔叔[对]我很好。","Chú tôi đối với tôi rất tốt."),("他们[对]客人特别热情。","Họ đặc biệt nhiệt tình với khách."),("老师对学生很关心。","Thầy rất quan tâm học sinh."),("你对他太好了。","Bạn đối với anh ấy tốt quá.")],
"note":"对 đứng trước tính từ: Sai: 我叔叔很好对我。"}],
"tip":"Khi tặng quà, người Trung Quốc tránh tặng đồng hồ (送钟, nghe như 送终 \"đưa tang\") và tránh số 4 (四 gần âm 死). Quà thường được nhận bằng hai tay và không mở ngay trước mặt."},
# ---------------- 17
{"title":"Vui buồn giận hờn","topic":"Cảm xúc, tính cách; 让 + người + cảm xúc, 对 + việc + 满意, 担心 / 怕 / 相信 + cả một câu",
"goals":["Nói cảm xúc: vui, buồn, giận, sợ, lo","Nói cái gì làm ai đó vui / buồn với 让","Dùng 对…满意 / 对…感到…","Dùng 担心 / 怕 / 相信 / 同意 + một câu"],
"dialogue":[("妈妈","龙，你怎么了？看起来不太开心。","Long, con sao vậy? Trông không vui lắm."),("龙","这次考试成绩不好，我很难过。","Lần thi này điểm không tốt, con buồn lắm."),("妈妈","别着急，也别生气。一次考试没关系。","Đừng vội, cũng đừng giận. Một lần thi không sao cả."),("龙","我怕您和爸爸不满意。","Con sợ bố mẹ không hài lòng."),("妈妈","好孩子，我们只关心你开不开心，不担心你的成绩。","Con ngoan, bố mẹ chỉ quan tâm con có vui không, không lo điểm số của con."),("龙","真的吗？您的话让我心里好多了。","Thật ạ? Lời mẹ làm con thấy trong lòng dễ chịu hơn nhiều."),("妈妈","我相信你下次一定能考好。你同意吗？","Mẹ tin lần sau con nhất định thi tốt. Con đồng ý không?"),("龙","同意！我愿意从今天开始认真复习。","Đồng ý ạ! Con sẵn sàng bắt đầu ôn bài chăm chỉ từ hôm nay.")],
"grammar":[
{"title":"让 + Người + Cảm xúc: làm ai cảm thấy…","formula":"Việc / Người + 让 + Người + (很) + Tính từ cảm xúc",
"explain":"<b>让</b> (đã học \"bảo ai làm gì\") còn dùng để nói một việc <b>khiến</b> ai đó có cảm xúc:<br>您的话<b>让</b>我心里好多了。 (Lời mẹ khiến con thấy dễ chịu hơn.)<br>这个消息<b>让</b>大家很高兴。<br>Hay gặp: 让人 + Adj: 让人生气 (khiến người ta tức), 让人担心.",
"examples":[("您的话[让]我心里好多了。","Lời mẹ làm con thấy trong lòng dễ chịu hơn nhiều."),("这件事[让]我很生气。","Việc này làm tôi rất tức."),("他的成绩让老师很满意。","Điểm của cậu ấy làm thầy rất hài lòng."),("下雨让人不开心。","Trời mưa làm người ta không vui.")],
"note":"Sai: 这件事生气我。 (tiếng Trung không dùng tính từ cảm xúc như động từ gây ra)."},
{"title":"对 + Việc + 满意 / 感到…","formula":"A + 对 + B + (很 / 不) + 满意 · A + 对 + B + 感到 + Tính từ",
"explain":"Thái độ <b>đối với</b> một việc, đối tượng được đưa lên trước bằng <b>对</b>:<br>我<b>对</b>这次考试的成绩很<b>满意</b>。 (hài lòng với…)<br>他<b>对</b>这个问题<b>感到</b>很奇怪。 (cảm thấy lạ về…)<br>Có thể bỏ đối tượng nếu đã rõ: 我怕您和爸爸<b>不满意</b>。",
"examples":[("我怕您和爸爸不[满意]。","Con sợ bố mẹ không hài lòng."),("经理[对]你的工作很满意。","Giám đốc rất hài lòng với công việc của bạn."),("大家对这件事感到很奇怪。","Mọi người thấy việc này rất lạ."),("我对现在的生活很满意。","Tôi rất hài lòng với cuộc sống hiện tại.")],
"note":"Sai: 我满意这次考试。 → Đúng: 我对这次考试很满意。"},
{"title":"担心 / 怕 / 相信 / 同意 + cả một câu","formula":"Chủ ngữ + 担心 / 怕 / 相信 / 同意 / 觉得 + [Chủ ngữ 2 + Vị ngữ]",
"explain":"Những động từ tâm lý này mang tân ngữ là <b>cả một câu</b>:<br>我<b>怕</b>[您和爸爸不满意]。<br>我<b>相信</b>[你下次一定能考好]。<br>妈妈<b>担心</b>[我晚上不睡觉]。<br>Phủ định đặt trước động từ chính: 我<b>不</b>相信他会迟到。",
"examples":[("我[怕]您和爸爸不满意。","Con sợ bố mẹ không hài lòng."),("我[相信]你下次一定能考好。","Mẹ tin lần sau con nhất định thi tốt."),("妈妈担心我晚上不睡觉。","Mẹ lo tối con không ngủ."),("你同意我们明天去吗？","Bạn có đồng ý mai chúng ta đi không?")],
"note":"担心 (lo, hướng về chuyện chưa xảy ra) ≈ 怕 nhưng 怕 còn nghĩa \"sợ\" thật sự: 我怕狗。"}],
"tip":"Người Trung Quốc ít nói thẳng \"我爱你\" với bố mẹ. Quan tâm thường thể hiện bằng câu hỏi \"吃饭了吗？\" (ăn cơm chưa?) hoặc \"多穿点儿\" (mặc thêm áo vào)."},
# ---------------- 18
{"title":"Chọn phòng trọ","topic":"Đánh giá, so sánh; 挺…的, 差不多 / 几乎 / 大概, 像 + B + 一样 và 跟 + B + 不同",
"goals":["Khen chê, so sánh nhà cửa, đồ vật","Nói \"khá…\" bằng 挺…的","Nói gần đúng: 差不多, 几乎, 大概","So sánh giống / khác: 像…一样, 跟…不同"],
"dialogue":[("小米","龙，你看的两个房子怎么样？","Long, hai căn phòng bạn đi xem thế nào?"),("龙","第一个挺好的，比较安静，可是有点儿旧。","Căn thứ nhất khá được, tương đối yên tĩnh, nhưng hơi cũ."),("小米","第二个呢？","Còn căn thứ hai?"),("龙","第二个是新的，房间像宾馆一样漂亮，就是离学校特别远。","Căn thứ hai mới, phòng đẹp như khách sạn, chỉ là cách trường rất xa."),("小米","两个房子的钱差不多吗？","Giá hai căn xấp xỉ nhau không?"),("龙","几乎一样，大概都是两千块一个月。","Gần như bằng nhau, khoảng hai nghìn tệ một tháng."),("小米","那主要看你喜欢什么。每个人的想法都跟别人不同。","Vậy chủ yếu xem bạn thích gì. Suy nghĩ của mỗi người đều khác người khác."),("龙","对我来说，安静最重要。我选第一个！","Với mình, yên tĩnh quan trọng nhất. Mình chọn căn thứ nhất!")],
"grammar":[
{"title":"挺 + Tính từ + 的: khá…, …phết","formula":"挺 + Tính từ / Động từ tâm lý + 的",
"explain":"<b>挺…的</b> nghĩa \"khá, rất\" trong khẩu ngữ, nhẹ và thân mật hơn 很:<br>第一个房子<b>挺</b>好<b>的</b>。 (khá được)<br>我<b>挺</b>喜欢他<b>的</b>。<br>Chữ 的 cuối thường có, nói nhanh có thể bỏ.",
"examples":[("第一个[挺]好的。","Căn thứ nhất khá được."),("这个地方[挺]安静的。","Chỗ này khá yên tĩnh."),("我挺喜欢这个城市的。","Tôi khá thích thành phố này."),("今天挺冷的，多穿点儿。","Hôm nay khá lạnh, mặc thêm vào.")],
"note":"挺 + 不 + Adj: 挺不错的 (khá tốt đấy) là lời khen rất hay dùng."},
{"title":"差不多 / 几乎 / 大概: gần như, khoảng","formula":"差不多 (+ Số / 一样) · 几乎 + Động từ / 一样 · 大概 + Số / Phán đoán",
"explain":"• <b>差不多</b>: xấp xỉ, gần bằng; đứng một mình làm vị ngữ được: 两个房子的钱<b>差不多</b>。<br>• <b>几乎</b>: gần như (sát mức tuyệt đối): <b>几乎</b>一样, <b>几乎</b>每天都去。<br>• <b>大概</b>: khoảng chừng, có lẽ (ước lượng, đoán): <b>大概</b>两千块, 他<b>大概</b>不来了。",
"examples":[("两个房子的钱[差不多]吗？","Giá hai căn xấp xỉ nhau không?"),("[几乎]一样。","Gần như bằng nhau."),("[大概]都是两千块一个月。","Khoảng hai nghìn tệ một tháng."),("他大概不来了。","Có lẽ anh ấy không đến nữa.")],
"note":"Chỉ 差不多 làm vị ngữ được: 我们差不多。 Sai: 我们几乎。"},
{"title":"A 像 B 一样 / A 跟 B 不同","formula":"A + 像 + B + 一样 (+ Tính từ) · A + 跟 + B + 不同 / 不一样",
"explain":"• <b>像…一样</b>: \"giống như\", dùng để ví von: 房间<b>像</b>宾馆<b>一样</b>漂亮。<br>• <b>跟…不同</b>: khác với: 每个人的想法都<b>跟</b>别人<b>不同</b>。 (= 不一样)<br>So với 跟…一样 (bằng, giống hệt) đã học: 像 thiên về <b>so sánh hình ảnh</b>.",
"examples":[("房间[像]宾馆一样漂亮。","Phòng đẹp như khách sạn."),("每个人的想法都[跟]别人不同。","Suy nghĩ của mỗi người đều khác người khác."),("他像他爸爸一样高。","Cậu ấy cao như bố."),("北方的冬天跟南方很不同。","Mùa đông miền Bắc rất khác miền Nam.")],
"note":"对我来说 = \"đối với tôi mà nói\", hay đi kèm khi nêu ý kiến riêng."}],
"tip":"Thuê nhà ở Trung Quốc thường \"押一付三\": cọc 1 tháng, trả trước 3 tháng tiền nhà."},
# ---------------- 19
{"title":"Thay đổi","topic":"Phát triển, thay đổi, trải nghiệm; 以为 và 认为, V + 成, 受到 / 得到 + danh từ",
"goals":["Kể về thay đổi trong cuộc sống","Phân biệt 以为 (tưởng, mà sai) và 认为 (cho rằng)","Dùng 变成 / 换成 / 写成: thành…","Dùng 受到 / 得到 + 影响 / 帮助"],
"dialogue":[("安娜","龙，你离开老家多少年了？","Long, bạn rời quê bao nhiêu năm rồi?"),("龙","四年了。上个月回去，我发现那里的变化特别大。","Bốn năm rồi. Tháng trước về, mình phát hiện ở đó thay đổi rất nhiều."),("安娜","怎么变了？","Thay đổi thế nào?"),("龙","以前的小路变成了大马路，城市发展得很快。我以为我会不认得路了，没想到很快就习惯了。","Đường nhỏ trước đây thành đường lớn, thành phố phát triển rất nhanh. Mình tưởng sẽ không nhận ra đường nữa, không ngờ nhanh chóng quen lại."),("安娜","你认为这是好的变化吗？","Bạn cho rằng đây là thay đổi tốt không?"),("龙","我认为是。大家的生活都受到了好的影响。","Mình cho là có. Cuộc sống của mọi người đều chịu ảnh hưởng tốt."),("安娜","你在这儿也得到了很多人的帮助吧？","Ở đây bạn cũng nhận được sự giúp đỡ của nhiều người nhỉ?"),("龙","是啊，遇到问题的时候，朋友们总是帮我。","Đúng vậy, khi gặp vấn đề, bạn bè luôn giúp mình.")],
"grammar":[
{"title":"以为 và 认为","formula":"以为 + (điều tưởng, sau đó thấy sai) · 认为 + (ý kiến, nhận định)",
"explain":"• <b>以为</b>: \"tưởng là\", thường <b>sai sự thật</b>: 我<b>以为</b>我会不认得路了，没想到很快就习惯了。<br>• <b>认为</b>: \"cho rằng\", nêu <b>quan điểm</b> nghiêm túc: 我<b>认为</b>这是好的变化。<br>没想到 (không ngờ) hay đi sau 以为.",
"examples":[("我[以为]我会不认得路了。","Tôi tưởng mình sẽ không nhận ra đường nữa."),("你[认为]这是好的变化吗？","Bạn cho rằng đây là thay đổi tốt không?"),("我以为你走了，原来你还在！","Tôi tưởng bạn đi rồi, hóa ra vẫn còn ở đây!"),("老师认为这个办法很好。","Thầy cho rằng cách này rất hay.")],
"note":"Sai: 我以为这个办法很好，所以我选了它。 (không có ý \"tưởng sai\" thì dùng 认为 / 觉得)."},
{"title":"V + 成: thành, thành ra","formula":"(A) + 变 / 换 / 写 / 看 / 翻译 + 成 + B",
"explain":"Bổ ngữ kết quả <b>成</b> nói A <b>biến thành</b> B:<br>小路<b>变成</b>了大马路。<br>把美元<b>换成</b>人民币 (đã gặp ở bài 4).<br>他把\"人\"<b>写成</b>了\"入\"。 (viết nhầm thành)<br>我把他<b>看成</b>了你。 (nhìn nhầm thành)",
"examples":[("以前的小路[变成]了大马路。","Đường nhỏ trước đây thành đường lớn."),("天气变冷了，雨变[成]了雪。","Trời trở lạnh, mưa thành tuyết."),("我把“大”写成了“太”。","Tôi viết \"大\" thành \"太\"."),("他把我看成了我哥哥。","Anh ấy nhìn nhầm tôi thành anh trai tôi.")],
"note":"变 (biến đổi, nội động từ) ≠ 变成 (biến thành cái gì, phải có tân ngữ)."},
{"title":"受到 / 得到 + Danh từ","formula":"受到 + 影响 / 欢迎 / 关心… · 得到 + 帮助 / 机会 / 回答…",
"explain":"Hai động từ đều nghĩa \"nhận được\", nhưng:<br>• <b>受到</b>: chịu, bị/được tác động (thụ động): <b>受到</b>影响, <b>受到</b>欢迎, <b>受到</b>关注<br>• <b>得到</b>: có được (thường là thứ tốt): <b>得到</b>帮助, <b>得到</b>机会<br>Tân ngữ thường là danh từ trừu tượng, có định ngữ phía trước: 得到了很多人<b>的</b>帮助。",
"examples":[("大家的生活都[受到]了好的影响。","Cuộc sống của mọi người đều chịu ảnh hưởng tốt."),("你也[得到]了很多人的帮助吧？","Bạn cũng nhận được sự giúp đỡ của nhiều người nhỉ?"),("这个电影很受欢迎。","Bộ phim này rất được hoan nghênh."),("他得到了去中国留学的机会。","Cậu ấy có được cơ hội du học Trung Quốc.")],
"note":"受欢迎 (được ưa chuộng) là cụm cực kỳ hay dùng."}],
"tip":"Hơn 40 năm qua, Trung Quốc thay đổi rất nhanh. Người ta hay nói \"日新月异\" (mỗi ngày mỗi khác) để tả sự thay đổi đó."},
# ---------------- 20
{"title":"Thế giới và văn hóa","topic":"Quốc gia, thành phố, lịch sử; 又 và 再, 到处 + 都, 以上 / 以下",
"goals":["Nói về đất nước, thành phố, văn hóa, lịch sử","Phân biệt 又 (lại, đã xảy ra) và 再 (lại, sẽ làm)","Nói khắp nơi với 到处 + 都","Dùng 以上 / 以下 với số"],
"dialogue":[("小米","龙，你又去博物馆了？","Long, bạn lại đi bảo tàng à?"),("龙","是啊，我总是对历史和文化很感兴趣。下个月我还想再去一次。","Ừ, mình luôn rất hứng thú với lịch sử và văn hóa. Tháng sau mình còn muốn đi lần nữa."),("小米","这个城市有很长的历史吧？","Thành phố này có lịch sử lâu đời nhỉ?"),("龙","对，有一千年以上的历史。到处都有老房子。","Đúng, có hơn một nghìn năm lịch sử. Khắp nơi đều có nhà cổ."),("小米","听说来这儿旅游的人来自世界上很多国家。","Nghe nói người đến đây du lịch đến từ nhiều nước trên thế giới."),("龙","是的。博物馆里有一段关于这个地方的电影，我看了两遍。","Đúng. Trong bảo tàng có một đoạn phim về nơi này, mình xem hai lượt."),("小米","下次咱们一块儿去吧！","Lần sau chúng ta cùng đi nhé!"),("龙","好！十八岁以下的学生不要钱，你还得买票。","Được! Học sinh dưới mười tám tuổi miễn phí, bạn vẫn phải mua vé.")],
"grammar":[
{"title":"又 và 再: lại","formula":"又 + V + 了 (đã lặp lại) · 再 + V (sẽ lặp lại)",
"explain":"Cả hai nghĩa \"lại, lần nữa\":<br>• <b>又</b>: việc lặp lại <b>đã xảy ra</b>: 你<b>又</b>去博物馆<b>了</b>？ (bạn lại đi rồi à?) — thường có 了.<br>• <b>再</b>: việc lặp lại <b>chưa xảy ra</b>, sẽ làm: 我还想<b>再</b>去一次。 请<b>再</b>说一遍。",
"examples":[("你[又]去博物馆了？","Bạn lại đi bảo tàng à?"),("下个月我还想[再]去一次。","Tháng sau tôi còn muốn đi lần nữa."),("他昨天又迟到了。","Hôm qua anh ấy lại đến muộn."),("明天再说吧。","Mai rồi nói tiếp.")],
"note":"Sai: 我昨天再去了。 (đã xảy ra → 又). Sai: 明天我又去。 (chưa xảy ra → 再)."},
{"title":"到处 + 都: khắp nơi đều","formula":"到处 + 都 + Động từ / 是 / 有…",
"explain":"<b>到处</b> = \"khắp nơi, chỗ nào cũng\", gần như luôn đi với <b>都</b>:<br><b>到处都</b>有老房子。<br>春天<b>到处都</b>是花。<br>我<b>到处</b>找你，可是找不到。 (tìm khắp nơi)",
"examples":[("[到处]都有老房子。","Khắp nơi đều có nhà cổ."),("春天到处[都]是花。","Mùa xuân khắp nơi đều là hoa."),("我到处找我的钥匙。","Tôi tìm chìa khóa khắp nơi."),("这个城市到处都是人。","Thành phố này đâu đâu cũng là người.")],
"note":"到处 là phó từ, đứng trước động từ, không đứng sau: Sai: 有到处老房子。"},
{"title":"以上 / 以下: trên / dưới","formula":"Số + 以上 / 以下 · …以上 (những điều trên)",
"explain":"• Số + <b>以上</b>: từ số đó trở lên: 一千年<b>以上</b>的历史 (hơn một nghìn năm)<br>• Số + <b>以下</b>: từ số đó trở xuống: 十八岁<b>以下</b>的学生<br>• Đứng riêng: <b>以上</b> = những điều nói ở trên: 以上是我的想法。",
"examples":[("有一千年[以上]的历史。","Có hơn một nghìn năm lịch sử."),("十八岁[以下]的学生不要钱。","Học sinh dưới mười tám tuổi miễn phí."),("六十分以上就可以了。","Từ sáu mươi điểm trở lên là được."),("以上是我的想法，谢谢大家。","Trên đây là suy nghĩ của tôi, cảm ơn mọi người.")],
"note":"来自 = đến từ (trang trọng): 他来自越南 = 他是从越南来的。"}],
"tip":"Bảo tàng Cố Cung (故宫博物院) ở Bắc Kinh là cung điện gỗ lớn nhất thế giới, có gần 600 năm lịch sử."},
# ---------------- 21
{"title":"Kế hoạch tương lai","topic":"Ôn tập HSK 3: dự định, lời khuyên; 得 (děi) / 应该 / 需要, 最好 + V, trạng ngữ Adj + 地 + V",
"goals":["Nói kế hoạch, dự định, khuyên ai đó","Phân biệt 得 (phải), 应该 (nên), 需要 (cần)","Khuyên với 最好","Dùng 地 để nói cách làm: 认真地学"],
"dialogue":[("小米","龙，听说你打算毕业以后去中国工作？","Long, nghe nói bạn định tốt nghiệp xong sang Trung Quốc làm việc?"),("龙","对。可是我的汉语还不行，得好好儿准备。","Đúng. Nhưng tiếng Trung của mình còn chưa được, phải chuẩn bị cho tốt."),("小米","你需要考HSK吗？","Bạn có cần thi HSK không?"),("龙","需要，公司要求HSK五级。我每天都很认真地学习。","Cần, công ty yêu cầu HSK 5. Mình học rất chăm chỉ mỗi ngày."),("小米","那你最好每天跟中国人聊聊天儿，比如在网上。","Vậy tốt nhất mỗi ngày bạn nói chuyện với người Trung Quốc một chút, ví dụ trên mạng."),("龙","好主意！我也应该多讲多说，不能只是看书。","Ý hay! Mình cũng nên nói nhiều, không thể chỉ đọc sách."),("小米","别忘记照顾身体，晚上不能睡得太晚。","Đừng quên giữ sức khỏe, buổi tối không được ngủ quá muộn."),("龙","知道了！我会每天开心地学下去。","Biết rồi! Mình sẽ vui vẻ học tiếp mỗi ngày.")],
"grammar":[
{"title":"得 (děi) / 应该 / 需要: phải, nên, cần","formula":"得 + V (phải, khẩu ngữ) · 应该 + V (nên) · 需要 + V / Danh từ (cần)",
"explain":"• <b>得</b> đọc <b>děi</b>: \"phải\" (khẩu ngữ, bắt buộc do hoàn cảnh): 我<b>得</b>好好儿准备。 Phủ định dùng <b>不用</b>, không nói 不得.<br>• <b>应该</b>: \"nên\" (lời khuyên, đạo lý): 我也<b>应该</b>多说。<br>• <b>需要</b>: \"cần\", mang được danh từ: 你<b>需要</b>考HSK吗？ 我<b>需要</b>你的帮助。<br>Chữ 得 có 3 cách đọc: dé (得到), de (说得好), děi (phải).",
"examples":[("我的汉语还不行，[得]好好儿准备。","Tiếng Trung tôi còn chưa được, phải chuẩn bị cho tốt."),("你[需要]考HSK吗？","Bạn có cần thi HSK không?"),("我也[应该]多讲多说。","Tôi cũng nên nói nhiều."),("太晚了，我得走了。","Muộn quá rồi, tôi phải đi đây.")],
"note":"Sai: 我不得去。 Đúng: 我不用去 (không cần đi)."},
{"title":"最好 + V: tốt nhất là…","formula":"(Chủ ngữ) + 最好 + (不 / 别) + Động từ",
"explain":"<b>最好</b> đưa ra <b>lời khuyên</b> mềm mỏng: \"tốt nhất là…\":<br>你<b>最好</b>每天跟中国人聊聊天儿。<br>Phủ định: 你<b>最好</b>别/不…: 你最好别喝太多咖啡。",
"examples":[("你[最好]每天跟中国人聊聊天儿。","Tốt nhất mỗi ngày bạn nói chuyện với người Trung Quốc."),("下雨了，你[最好]带伞。","Mưa rồi, tốt nhất bạn mang ô."),("你最好别晚上喝咖啡。","Tốt nhất bạn đừng uống cà phê buổi tối."),("最好早点儿去，人少。","Tốt nhất đi sớm một chút, ít người.")],
"note":"最好 còn nghĩa \"tốt nhất\" (so sánh nhất): 他是我最好的朋友。"},
{"title":"Tính từ + 地 + Động từ: làm thế nào","formula":"(Phó từ) + Tính từ + 地 + Động từ",
"explain":"<b>地</b> (đọc de) nối <b>trạng ngữ</b> với động từ, nói <b>cách</b> làm việc:<br>我每天都很认真<b>地</b>学习。 (học một cách chăm chỉ)<br>Tính từ lặp lại cũng hay dùng: 好好儿<b>地</b>休息, 慢慢<b>地</b>说.<br>Ba chữ \"de\": 的 (trước danh từ) · 地 (trước động từ) · 得 (sau động từ).",
"examples":[("我每天都很认真[地]学习。","Mỗi ngày tôi học rất chăm chỉ."),("我会每天开心[地]学下去。","Tôi sẽ vui vẻ học tiếp mỗi ngày."),("他高兴地说：“我考上了！”","Cậu ấy vui vẻ nói: \"Mình đỗ rồi!\""),("请慢慢地说。","Làm ơn nói chậm thôi.")],
"note":"认真的学生 (học sinh chăm chỉ, 的 + danh từ) · 认真地学习 (học chăm chỉ, 地 + động từ) · 学得很认真 (得 sau động từ)."}],
"tip":"Chúc mừng em học xong HSK 3! Thi HSK 3 (HSK 3.0) gồm nghe, đọc, viết; đạt khoảng 60% là qua. Học xong bài này làm thử bài thi tổng HSK 3 trong app nha."},
]
